INSERT INTO `training_course` (`root_id`,`version`,`is_current`,`code`,`title`,`subtitle`,`summary`,`level`,`credit`,`duration_minutes`,`industry`,`biz_tags`,`lecturer`,`media_type`,`media_count`,`comment_count`,`audit_count`,`status`,`sort`,`creator`,`updater`,`deleted`,`tenant_id`) VALUES
  (NULL, 1, b'1', 'A0101', '公司业务全景与产品线认知', NULL, '理解客户需求如何转化为防腐保温产品、施工与交付方案', 1, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 1, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (NULL, 1, b'1', 'A0102', '岗位职责与职业行为规范', NULL, '理解岗位授权、诚信记录、团队交接和异常上报', 1, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 2, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (NULL, 1, b'1', 'A0201', '石油化工现场安全通识', NULL, '识别现场危险源并掌握许可、隔离、防护和停工原则', 1, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 3, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (NULL, 1, b'1', 'B0102', '喷砂抛丸设备操作与维护', NULL, '理解设备组成、表面处理质量、点检和安全维护', 2, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 4, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (NULL, 1, b'1', 'B0202', '涂料调配 稀释与适用期控制', NULL, '按产品文件识读配比、调配、稀释和适用期要求', 2, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 5, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (NULL, 1, b'1', 'B0301', '高压无气喷涂操作', NULL, '理解无气喷涂设备、雾化、走枪、成膜与高压注入风险', 2, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 6, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (NULL, 1, b'1', 'B0305', '涂层缺陷识别与返修', NULL, '能够收集证据、判别缺陷、制定受控返修和复检闭环', 2, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 7, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (NULL, 1, b'1', 'B0501', '3PE 三层聚乙烯外防腐工艺', NULL, '理解FBE底层、胶粘层和聚乙烯外层的界面及质量控制', 2, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 8, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (NULL, 1, b'1', 'B0502', '环氧粉末 FBE 熔结防腐', NULL, '理解粉末储运、基材准备、热熔固化、检测和修补', 2, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 9, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (NULL, 1, b'1', 'G0101', '施工方案编制与技术交底', NULL, '把设计、材料、施工资源、质量和风险转化为可执行方案', 3, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 10, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (NULL, 1, b'1', 'G0102', '工艺卡与作业指导书应用', NULL, '将技术参数、步骤、检验点和异常处置落实到受控现场文件', 3, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 11, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (NULL, 1, b'1', 'G0201', '防腐保温工程验收标准', NULL, '依据合同、设计和现行适用规范组织过程验收、复验与交付', 3, 2.00, 45, '防腐保温', '["云培训学院"]', '云培训学院', 1, 1, 0, 0, 3, 12, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1);
INSERT INTO `training_question` (`qtype`,`stem`,`options_json`,`answer`,`analysis`,`difficulty`,`category_id`,`status`,`creator_id`,`creator_name`,`creator`,`deleted`,`tenant_id`) VALUES
  (1, '公司防腐保温业务的主要服务对象是下列哪一类？', '[{"key": "A", "text": "石化、化工、电力、市政供热等工业装置"}, {"key": "B", "text": "家用电器制造车间"}, {"key": "C", "text": "汽车整车装配线"}, {"key": "D", "text": "食品冷链零售门店"}]', 'A', '防腐保温主要面向工业装置与工业管道，核心客户集中在石化、化工、电力与市政供热领域。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '下列属于管道外防腐主流工艺的是？', '[{"key": "A", "text": "3PE 三层聚乙烯防腐"}, {"key": "B", "text": "阳极氧化处理"}, {"key": "C", "text": "电镀锌"}, {"key": "D", "text": "表面渗碳"}]', 'A', '埋地钢质管道外防腐以 3PE、FBE、环氧煤沥青等涂层工艺为主。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '公司产品线中的“保温”主要解决什么问题？', '[{"key": "A", "text": "减少热量散失、防止冻凝与烫伤"}, {"key": "B", "text": "提高金属导电性"}, {"key": "C", "text": "增加结构承载能力"}, {"key": "D", "text": "降低材料密度"}]', 'A', '保温（绝热）的作用是减少热损失、防冻防凝，并降低表面温度防止人员烫伤。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '岩棉、玻璃棉、硅酸铝棉属于下列哪类材料？', '[{"key": "A", "text": "绝热保温材料"}, {"key": "B", "text": "防腐涂料"}, {"key": "C", "text": "结构钢材"}, {"key": "D", "text": "密封胶粘剂"}]', 'A', '这三类均为无机纤维类绝热材料，用于设备与管道的保温隔热。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '环氧粉末（FBE）主要应用于下列哪个部位？', '[{"key": "A", "text": "管道及管件外表面的熔结防腐涂层"}, {"key": "B", "text": "混凝土外加剂"}, {"key": "C", "text": "电缆绝缘层"}, {"key": "D", "text": "建筑幕墙玻璃"}]', 'A', 'FBE 通过静电喷涂并熔融固化形成防腐层，是管道外防腐的常用底层材料。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '公司承接的防腐保温工程项目，业务链条通常起始于？', '[{"key": "A", "text": "现场勘查与需求确认"}, {"key": "B", "text": "竣工结算"}, {"key": "C", "text": "备品备件采购"}, {"key": "D", "text": "人员招聘"}]', 'A', '工程业务一般按“勘查—方案—施工—验收—结算”推进，起点是现场勘查与需求确认。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '下列哪一项不属于防腐保温工程的典型客户行业？', '[{"key": "A", "text": "石油化工"}, {"key": "B", "text": "电力热电"}, {"key": "C", "text": "市政供热"}, {"key": "D", "text": "服装零售"}]', 'D', '服装零售与工业防腐保温无直接业务关联。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '3PE 防腐层中的“PE”指的是？', '[{"key": "A", "text": "聚乙烯"}, {"key": "B", "text": "聚酯"}, {"key": "C", "text": "环氧树脂"}, {"key": "D", "text": "聚氨酯"}]', 'A', 'PE 即 Polyethylene（聚乙烯），是 3PE 结构的最外层。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '公司对外宣传中的“一体化解决方案”通常指？', '[{"key": "A", "text": "材料供应 + 施工 + 验收全过程服务"}, {"key": "B", "text": "仅提供材料供应"}, {"key": "C", "text": "仅提供方案设计"}, {"key": "D", "text": "仅提供物流运输"}]', 'A', '一体化指覆盖材料、施工与验收的完整服务能力，可减少界面责任推诿。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '了解客户需求时，首要关注的信息通常是？', '[{"key": "A", "text": "介质温度、压力与腐蚀环境等工况条件"}, {"key": "B", "text": "客户办公电脑的品牌"}, {"key": "C", "text": "厂区绿化面积"}, {"key": "D", "text": "员工平均年龄"}]', 'A', '工况条件决定材料选型与工艺方案，是技术交流的第一步。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '公司防腐保温业务通常包含下列哪些产品与服务？', '[{"key": "A", "text": "防腐涂料供应"}, {"key": "B", "text": "绝热保温材料供应"}, {"key": "C", "text": "现场防腐保温施工"}, {"key": "D", "text": "工程验收技术服务"}]', 'A,B,C,D', '公司业务覆盖材料供应、现场施工与验收技术服务，构成完整链条。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '选择防腐方案时需要重点考虑的因素有哪些？', '[{"key": "A", "text": "介质温度与运行工况"}, {"key": "B", "text": "环境腐蚀性与敷设方式"}, {"key": "C", "text": "设计使用寿命"}, {"key": "D", "text": "管道外表面油漆颜色"}]', 'A,B,C', '材料与工艺选择取决于工况、环境与寿命要求，与表面颜色无关。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '保温工程的常见应用部位包括？', '[{"key": "A", "text": "蒸汽与热水管道"}, {"key": "B", "text": "储罐与塔器"}, {"key": "C", "text": "换热设备"}, {"key": "D", "text": "办公桌椅"}]', 'A,B,C', '保温针对有热损失的工业设备与管道，与办公家具无关。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '下列属于绝热保温材料的有哪些？', '[{"key": "A", "text": "岩棉"}, {"key": "B", "text": "玻璃棉"}, {"key": "C", "text": "硅酸铝棉"}, {"key": "D", "text": "环氧富锌底漆"}]', 'A,B,C', '环氧富锌底漆属防腐涂料，不具备绝热功能。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '与客户洽谈项目时通常需要明确的信息有哪些？', '[{"key": "A", "text": "工程量与工期要求"}, {"key": "B", "text": "执行的技术标准"}, {"key": "C", "text": "现场施工条件"}, {"key": "D", "text": "结算与付款方式"}]', 'A,B,C,D', '上述四项均直接影响报价、组织与合同条款，需在洽谈阶段明确。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '防腐与保温是两种功能不同的工程措施：前者防止腐蚀，后者减少热损失。', '', '对', '两者目标不同，常配合使用但不可相互替代。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '3PE 防腐层由环氧粉末底层、胶粘剂中间层和聚乙烯面层三层构成。', '', '对', '这是 3PE 的标准结构。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '保温材料可以脱离介质温度随意选型，与工况无关。', '', '错', '材料耐温等级必须匹配介质温度，否则会失效甚至碳化。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, 'FBE 是环氧粉末涂层的英文缩写。', '', '对', 'FBE 即 Fusion Bonded Epoxy。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '公司的业务仅涉及涂料销售，不包含现场施工。', '', '错', '公司业务包含现场防腐保温施工与验收技术服务。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '石化、电力、市政供热等行业都属于防腐保温工程的典型服务领域。', '', '对', '这些行业存在大量需防腐与保温的管道和设备。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '熟悉公司产品线有助于现场准确识别材料与工艺。', '', '对', '识别材料是判断工艺与质量的前提。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '保温工程的目的一是减少热损失，二是防止管道冬季冻凝。', '', '对', '防冻防凝是保温的重要功能之一。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '客户的行业背景与防腐方案选择没有关系。', '', '错', '行业决定介质与腐蚀环境，直接影响方案选择。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '工程类项目通常需要现场勘查后再确定技术方案。', '', '对', '现场条件（敷设方式、环境、空间）是方案确定的重要依据。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述公司防腐保温业务的主要服务对象与典型应用场景。', '', '主要服务石化、化工、电力、市政供热等行业客户；典型场景包括埋地及架空金属管道、储罐、换热器、塔器等设备的防腐蚀与绝热保温，既有新建工程也有检修改造工程。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述防腐与保温两类工程措施的目的差异。', '', '防腐通过涂层、阴极保护等手段阻止或延缓金属腐蚀，延长设备使用寿命；保温利用绝热层减少热量散失或防止介质冻结，同时降低外表面温度以防烫伤，服务于工艺稳定与节能。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '列举公司产品线中至少三类材料并说明其用途。', '', '①防腐涂料（如环氧富锌底漆、聚氨酯面漆）：用于钢结构和设备表面的防腐蚀；②绝热材料（岩棉、玻璃棉、硅酸铝棉）：用于管道与设备的保温隔热；③管道防腐层材料（环氧粉末、聚乙烯及胶粘剂）：用于埋地管道的外防腐。', NULL, 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '承接防腐保温项目时，前期需要向客户确认哪些关键信息？', '', '需确认介质温度与压力、腐蚀环境与敷设方式、工程量与工期、设计寿命与执行标准、现场施工条件（脚手架、动火、用水用电限制）、验收要求与结算方式。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '为什么现场人员需要了解公司业务全景与产品线？', '', '有助于准确识别材料与对应工艺、判断施工要点与质量控制点；在与客户、监理沟通时表述准确、减少歧义，避免用错材料或工艺造成返工与质量风险。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某化工厂反映“蒸汽管道外面包了保温棉，但人员仍被烫伤”。请分析可能原因并提出处理思路。', '', '可能原因：①保温层厚度不足或选材耐温等级不够；②保温层受潮含水，导热系数大幅上升；③外护层破损、保温层脱落或存在冷桥；④施工时局部漏包（阀门、法兰、支架处）。处理思路：现场检测外表面温度与保温层厚度，更换或加厚保温层，修复外护与防潮层，对漏包部位补做保温，并复测表面温度满足防烫要求。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '项目部准备承接一个新建化工厂的蒸汽管道保温工程，请列出开工前需要收集的基本信息。', '', '需收集：管道规格与介质参数（温度、压力）、敷设方式（架空/管廊/埋地）、工程量清单与工期节点、执行标准与设计保温厚度、现场施工条件与安全要求（动火、高处作业、受限空间）、材料到货计划与验收要求、以及与其他专业的交叉作业安排。', NULL, 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '现场新员工把岩棉当成了“防腐涂料”准备刷在设备表面。请指出错误并说明正确做法。', '', '岩棉是绝热保温材料，不具备防腐功能，直接用于钢表面无法阻止腐蚀。正确做法是先按设计要求完成表面处理与防腐涂层施工，再安装保温层并做防潮层与外护层，保温材料不得替代防腐涂层。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '客户问：“你们的 3PE 防腐和普通刷漆有什么区别？”请用通俗语言解释。', '', '普通刷漆是常温固化的薄涂层，主要起装饰和一般防腐作用；3PE 是工厂化生产的复合防腐层，由环氧粉末底层、胶粘剂中间层和聚乙烯面层组成，总厚度大、机械强度高、抗阴极剥离与抗土壤应力能力强，专用于埋地和重要工业管道，设计寿命通常在 30 年以上。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某市政供热工程要求必须在采暖季前完工，作为刚入职的现场人员，你应重点关注哪些业务环节？', '', '应重点关注：材料进场验收与到货节点、施工工序衔接（表面处理→防腐→保温→外护）、隐蔽工程验收与影像留存、关键节点的质量检查、进度偏差预警与上报、以及安全防护措施落实，确保按期且质量合格地完成交付。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '防腐保温施工中，负责按工艺要求完成表面处理与涂层施工的岗位是？', '[{"key": "A", "text": "涂装工"}, {"key": "B", "text": "资料员"}, {"key": "C", "text": "材料采购员"}, {"key": "D", "text": "安全总监"}]', 'A', '涂装工承担表面处理与涂装作业，是防腐施工的直接实施岗位。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '施工班组长在现场的首要职责是？', '[{"key": "A", "text": "组织作业、分配任务并对现场安全与质量负责"}, {"key": "B", "text": "负责公司财务报表"}, {"key": "C", "text": "负责客户合同签订"}, {"key": "D", "text": "负责产品研发设计"}]', 'A', '班组长是现场组织与责任的第一责任人，负责安全、质量与进度。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '进入施工现场前，作业人员必须完成的事项是？', '[{"key": "A", "text": "接受入场安全教育并考试合格"}, {"key": "B", "text": "先领取当月工资"}, {"key": "C", "text": "先办理离职手续"}, {"key": "D", "text": "先提交专利申请"}]', 'A', '入场安全教育是法定前置条件，未通过不得进入现场作业。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '关于劳动纪律，下列做法正确的是？', '[{"key": "A", "text": "按规定作息、不擅自离岗、不串岗"}, {"key": "B", "text": "作业时随时接听私人电话"}, {"key": "C", "text": "可以带无关人员进入现场"}, {"key": "D", "text": "可以自行更改作业内容"}]', 'A', '遵守作息与岗位纪律是基本职业行为要求。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '发现安全隐患时，作业人员的正确做法是？', '[{"key": "A", "text": "立即停止作业并上报"}, {"key": "B", "text": "先完成手头工作再说"}, {"key": "C", "text": "自行处理不告诉任何人"}, {"key": "D", "text": "拍照发到朋友圈"}]', 'A', '发现隐患应先停工、上报并等待处理，严禁冒险作业。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '施工记录（如涂层厚度、潮湿天气记录）应由谁按要求填写？', '[{"key": "A", "text": "作业人员或指定记录人按实填写"}, {"key": "B", "text": "随便口头说一下即可"}, {"key": "C", "text": "由客户代填"}, {"key": "D", "text": "事后凭记忆补填"}]', 'A', '施工记录必须及时、真实、可追溯，不得事后虚构。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '下列哪项属于员工职业行为规范的要求？', '[{"key": "A", "text": "爱护设备工具、节约材料、保持现场整洁"}, {"key": "B", "text": "把材料带回家自用"}, {"key": "C", "text": "在禁烟区吸烟"}, {"key": "D", "text": "私自改动机具参数"}]', 'A', '爱护公物、节约用料、文明施工是职业行为规范的基本内容。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '与客户或监理沟通时，正确的态度是？', '[{"key": "A", "text": "尊重、如实说明情况、不夸大不隐瞒"}, {"key": "B", "text": "隐瞒质量问题避免麻烦"}, {"key": "C", "text": "与客户争执推卸责任"}, {"key": "D", "text": "随意承诺做不到的事"}]', 'A', '诚信沟通是职业操守，也是工程质量管理的基础。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '岗位职责说明书中“谁操作谁负责”体现的原则是？', '[{"key": "A", "text": "岗位责任制"}, {"key": "B", "text": "集体免责制"}, {"key": "C", "text": "领导全责制"}, {"key": "D", "text": "随机分配制"}]', 'A', '岗位责任制明确各岗位的具体职责与责任边界。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '在防腐保温班组中，质检员的主要职责是？', '[{"key": "A", "text": "对施工质量进行检验与记录，判定是否合格"}, {"key": "B", "text": "负责安排施工进度"}, {"key": "C", "text": "负责采购原材料"}, {"key": "D", "text": "负责发放工资"}]', 'A', '质检员负责过程检验与质量判定，把好质量关。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '防腐保温作业人员的岗位职责通常包括哪些？', '[{"key": "A", "text": "按工艺文件与交底要求施工"}, {"key": "B", "text": "正确使用与保管工机具"}, {"key": "C", "text": "如实填写施工记录"}, {"key": "D", "text": "做好本岗位安全防护"}]', 'A,B,C,D', '上述四项均为岗位职责的组成部分。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '进入施工现场的着装与劳保要求包括？', '[{"key": "A", "text": "正确佩戴安全帽"}, {"key": "B", "text": "穿工作服与防护鞋"}, {"key": "C", "text": "按作业类型佩戴防护眼镜、防尘口罩"}, {"key": "D", "text": "穿拖鞋以便凉快"}]', 'A,B,C', '现场严禁穿拖鞋等不符合安全要求的着装。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '下列哪些行为违反职业行为规范？', '[{"key": "A", "text": "擅自离岗"}, {"key": "B", "text": "在禁火区吸烟"}, {"key": "C", "text": "隐瞒质量问题"}, {"key": "D", "text": "按规定填写记录"}]', 'A,B,C', '按规定填写记录是应尽职责，不属于违规行为。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '保持现场整洁与文明施工的意义有？', '[{"key": "A", "text": "减少绊倒、割伤等安全事故"}, {"key": "B", "text": "便于材料清点与质量检查"}, {"key": "C", "text": "提升企业外部形象"}, {"key": "D", "text": "便于掩盖施工缺陷"}]', 'A,B,C', '整洁现场是为安全与质量服务，不能用于掩盖问题。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '员工在质量与安全方面应承担的责任包括？', '[{"key": "A", "text": "严格执行工艺文件与操作规程"}, {"key": "B", "text": "发现异常及时报告"}, {"key": "C", "text": "拒绝违章指挥"}, {"key": "D", "text": "擅自更改工艺参数"}]', 'A,B,C', '擅自更改工艺参数属违规行为，可能造成质量与安全事故。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '未经入场安全教育的人员不得进入施工现场作业。', '', '对', '入场安全教育是强制性要求。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '发现安全隐患可以先继续干活，等下班后再上报。', '', '错', '发现隐患应立即停止作业并上报。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '施工记录可以在工程结束后凭记忆统一补填。', '', '错', '记录必须随施工过程及时、如实填写，事后补填属违规。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '爱护机具、节约材料属于职业行为规范的要求。', '', '对', '这是文明施工与职业素养的基本体现。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '员工有权拒绝违章指挥。', '', '对', '安全生产法赋予从业人员拒绝违章指挥的权利。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '岗位职责只对班组长有约束力，普通员工不必了解。', '', '错', '岗位责任制对每个岗位都有明确职责要求。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '在禁火区吸烟属于严重违反现场纪律的行为。', '', '对', '禁火区吸烟可能直接引发火灾爆炸事故。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '把施工现场的材料带回家自用属于合理利用。', '', '错', '这属于侵占公司财物，是严重违纪行为。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '与客户沟通时可以适当夸大施工质量以争取好评。', '', '错', '应如实沟通，不得夸大或隐瞒。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '遵守劳动纪律与作息安排是员工的基本义务。', '', '对', '遵守纪律是劳动合同与企业管理的基本要求。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述涂装工在防腐施工中的主要岗位职责。', '', '按技术交底与工艺文件要求完成表面处理、涂料调配与涂装作业；正确使用喷砂、喷涂等机具；控制涂层厚度与外观质量；如实填写施工与自检记录；做好本岗位安全防护与现场清理。', NULL, 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '进入石油化工防腐保温施工现场前，人员需要满足哪些基本要求？', '', '须接受入场安全教育并考试合格，办理入场证件；正确佩戴劳保用品；了解现场危险源与应急路线；接受作业前安全技术交底；特种作业须持证上岗；身体条件符合作业要求。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '发现同班人员违章作业时，应当如何处置？', '', '应立即予以制止并提醒风险，同时向班组长或安全员报告；若违章可能导致事故且对方拒不改正，应停止相关作业并上报，不得因情面而放任，避免发生事故后共同承担责任。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '为什么施工记录必须随施工过程及时填写而不能事后补填？', '', '记录是质量追溯与验收的依据。及时填写能真实反映当时条件（天气、温度、材料批次、工序参数）；事后补填容易遗漏或失真，一旦出现质量问题无法追溯责任，验收时也可能不被认可。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '作为新入职员工，如何快速熟悉自己的岗位职责与行为规范？', '', '认真阅读岗位说明书与公司管理制度，参加岗前培训与安全交底；跟随老师傅学习标准操作；对照工艺文件与作业指导书执行；定期自查执行偏差，主动向班组长确认不清楚的要求。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '现场一员工为赶进度，在未完成表面处理的情况下直接刷涂底漆。作为班组质检员你应如何处理？', '', '应立即制止该作业并要求返工：先停工，向班组长汇报；说明未达除锈等级直接涂装会导致涂层附着力不足、早期起皮脱落，属重大质量隐患；按工艺要求重新进行表面处理并检验合格后再涂装；同时记录事件并纳入班组质量教育，避免再次发生。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某员工在受限空间作业时感到头晕，同伴想让他“先忍一忍把活干完”。请指出正确做法。', '', '必须立即撤离受限空间并呼救，严禁继续作业。正确做法：立即停止作业、撤出人员到通风安全处；报告现场负责人并启动应急程序；检测受限空间气体与含氧量，查明原因并落实强制通风、监护等措施后方可复工；作业必须坚持“先通风、再检测、后作业”，严禁盲目施救。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '新员工第一天上班，把个人背包和饮料放在了作业通道上。请说明为什么不合适。', '', '作业通道必须保持畅通，堆放个人物品属于现场文明施工违规，可能导致人员绊倒、阻碍应急疏散与材料运输。正确做法是将个人物品存放在指定区域，并保持作业面整洁有序。', NULL, 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '客户在现场提出希望“少刷一道面漆以节省成本”，作为现场人员你应如何回应？', '', '应礼貌说明涂层道数与厚度是设计文件与执行标准的要求，减少道数会导致涂层厚度不足、防腐寿命下降，可能造成验收不合格和后期返修损失；如客户确有优化需求，应通过设计或监理单位正式变更流程处理，不得私自减少工序。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '班组内两人因工具使用发生争执，影响作业进度。作为班组长应如何处理？', '', '立即制止争执、恢复作业秩序；分别了解原因，按公共工具使用规定明确使用次序与责任人；强调团队协作与现场纪律；对违反纪律者按班组管理规定处理并记录；同时完善工具领用与交接登记，避免再次发生。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '进入石油化工生产区域，最基本的安全要求是？', '[{"key": "A", "text": "正确佩戴安全帽等劳保用品并遵守入场规定"}, {"key": "B", "text": "穿短袖凉鞋以便散热"}, {"key": "C", "text": "直接进入装置区参观"}, {"key": "D", "text": "携带火种以备夜间照明"}]', 'A', '石化现场属高危区域，劳保穿戴与入场规定是首要要求。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '下列哪项属于石化现场严禁携带入内的物品？', '[{"key": "A", "text": "香烟与打火机"}, {"key": "B", "text": "记录本"}, {"key": "C", "text": "测厚仪"}, {"key": "D", "text": "安全帽"}]', 'A', '火种严禁带入生产区域，防止引燃可燃气体。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '在装置区闻到明显刺激性气味并看到白雾，正确做法是？', '[{"key": "A", "text": "迅速撤离至上风向安全区域并上报"}, {"key": "B", "text": "凑近查看是什么物质"}, {"key": "C", "text": "原地继续作业"}, {"key": "D", "text": "打开手机拍照发群"}]', 'A', '应第一时间撤离并上报，禁止靠近未知泄漏源。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '动火作业前必须完成的关键环节是？', '[{"key": "A", "text": "办理动火作业许可证并进行气体检测"}, {"key": "B", "text": "直接焊接以节省时间"}, {"key": "C", "text": "先开工后补票"}, {"key": "D", "text": "只需口头通知同事"}]', 'A', '动火作业须审批、检测合格并落实监护措施。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '受限空间作业必须坚持的原则是？', '[{"key": "A", "text": "先通风、再检测、后作业"}, {"key": "B", "text": "先作业、后通风"}, {"key": "C", "text": "边作业边检测且无需监护"}, {"key": "D", "text": "只要戴防毒面具即可入内"}]', 'A', '受限空间作业必须先通风、检测合格并全程监护。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '高处作业时，防止坠落最有效的措施是？', '[{"key": "A", "text": "正确系挂安全带并高挂低用"}, {"key": "B", "text": "靠感觉保持平衡"}, {"key": "C", "text": "快速通过减少暴露时间"}, {"key": "D", "text": "手扶栏杆即可"}]', 'A', '安全带是高处作业防坠落的最后屏障，必须高挂低用、系挂牢固。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '“五同时”原则中的一项是把安全工作与生产工作？', '[{"key": "A", "text": "同时计划、同时布置、同时检查、同时总结、同时评比"}, {"key": "B", "text": "分开由不同部门负责"}, {"key": "C", "text": "仅在生产旺季开展"}, {"key": "D", "text": "完全交由承包商负责"}]', 'A', '五同时强调安全与生产同计划、同布置、同检查、同总结、同评比。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '使用手持电动工具前应重点检查的是？', '[{"key": "A", "text": "电线绝缘、接地（漏电保护）与外壳完好性"}, {"key": "B", "text": "工具的品牌颜色"}, {"key": "C", "text": "工具箱的重量"}, {"key": "D", "text": "使用者的工龄"}]', 'A', '漏电是手持电动工具的主要风险，须检查绝缘、接地与漏电保护。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '发现同事触电，首先应当做的是？', '[{"key": "A", "text": "切断电源或用绝缘物脱离电源后施救"}, {"key": "B", "text": "直接用手拉开触电者"}, {"key": "C", "text": "先拍照留存证据"}, {"key": "D", "text": "先询问触电原因"}]', 'A', '救护者必须先脱离电源，严禁直接接触触电者以免自身触电。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '石化现场发生火情的报警电话通常是？', '[{"key": "A", "text": "内部火警/调度电话，必要时拨 119"}, {"key": "B", "text": "110"}, {"key": "C", "text": "120"}, {"key": "D", "text": "12345"}]', 'A', '应首先报告现场调度并启动厂内应急响应，必要时拨打 119。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '进入石化装置区必须遵守的安全要求包括？', '[{"key": "A", "text": "接受入场安全教育"}, {"key": "B", "text": "正确穿戴劳保用品"}, {"key": "C", "text": "不得携带火种"}, {"key": "D", "text": "按指定路线行走"}]', 'A,B,C,D', '四项均为装置区基本安全要求。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '下列属于石化现场常见危险源的有？', '[{"key": "A", "text": "可燃有毒气体泄漏"}, {"key": "B", "text": "高温设备与管道"}, {"key": "C", "text": "转动机械与电气设备"}, {"key": "D", "text": "办公区打印机"}]', 'A,B,C', '打印机不属于石化典型作业危险源。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '受限空间作业前的必备措施包括？', '[{"key": "A", "text": "办理作业许可"}, {"key": "B", "text": "气体检测合格"}, {"key": "C", "text": "强制通风"}, {"key": "D", "text": "设置专人监护"}]', 'A,B,C,D', '受限空间作业须审批、通风、检测、监护四要素齐备。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '高处作业的安全要求包括？', '[{"key": "A", "text": "作业前检查作业面与安全带"}, {"key": "B", "text": "工具系防坠绳防止坠落"}, {"key": "C", "text": "下方设置警戒隔离"}, {"key": "D", "text": "遇六级以上大风停止露天高处作业"}]', 'A,B,C,D', '四项均为高处作业的强制安全要求。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '发生可燃气体泄漏时的正确做法包括？', '[{"key": "A", "text": "立即撤离至上风向"}, {"key": "B", "text": "报告调度并启动应急"}, {"key": "C", "text": "严禁使用非防爆电器与手机"}, {"key": "D", "text": "在泄漏区点火确认是否可燃"}]', 'A,B,C', '在泄漏区点火极其危险，属于严重错误行为。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '进入石化生产区域必须正确佩戴安全帽。', '', '对', '安全帽可防止物体打击，是进入现场的基本防护。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '只要速度快，就可以不办动火票直接焊接。', '', '错', '动火作业必须办理作业许可并完成气体检测。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '受限空间作业可以先进入作业，再补做气体检测。', '', '错', '必须先通风、检测合格后方可进入作业。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '高处作业安全带应高挂低用。', '', '对', '高挂低用可有效减少坠落距离与冲击力。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '发现有人触电，应首先用手把人拉开。', '', '错', '直接接触会导致施救者同时触电，应先切断电源。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '可燃气体泄漏时应向上风向撤离。', '', '对', '上风向是相对安全的撤离方向。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '在装置区可以使用非防爆手机随意拍照。', '', '错', '非防爆电子设备可能成为点火源，需按规定使用。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '现场安全与生产任务应当同时计划、布置、检查。', '', '对', '这是“五同时”原则的要求。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '劳保用品可以由个人随意改造成更舒适的样子。', '', '错', '劳保用品需保持原有防护性能，不得擅自改造。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '作业中发现安全隐患可以先干完活再报告。', '', '错', '应立即停止作业并上报处理。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述进入石油化工施工区域的通用安全要求。', '', '接受入场安全教育并考试合格、办理入场证；正确穿戴安全帽、工作服、防护鞋等劳保用品；不携带火种与香烟；按指定路线行走、不擅自进入非作业区域；熟悉应急集合点与撤离路线；服从现场安全人员管理。', NULL, 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '动火作业需要落实哪些关键安全措施？', '', '办理动火作业许可证并经审批；作业前进行可燃气体检测并合格；清理或隔离作业区可燃物；配备灭火器材与接火盘；设置专职监护人与看火人；作业中持续监测、作业后检查有无残火并确认安全。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '受限空间作业的“四不进入”主要内容是什么？', '', '未经审批不进入；未进行检测或检测不合格不进入；未采取通风措施不进入；无专人监护不进入。核心是先通风、再检测、后作业。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述高处作业的安全防护要点。', '', '作业前检查平台、护栏与安全带完好性；正确佩戴并高挂低用安全带；工具与材料系挂防坠绳或放入工具袋；下方设置警戒区并挂警示牌；遇六级及以上大风、雷雨等恶劣天气停止露天高处作业。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '现场发现可燃气体泄漏时，应如何处置？', '', '立即停止作业、切断可能的点火源（禁用非防爆电器与手机），迅速向上风向或安全区域撤离；就近报告班组长与厂方调度，启动应急预案；协助设置警戒、禁止无关人员进入；不得擅自处置泄漏点，待专业人员确认安全后再恢复作业。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某作业人员为了抄近路，翻越装置区围栏进入非作业区域。请分析风险并给出处置建议。', '', '风险：非作业区域可能存在高温、高压、有毒有害介质泄漏与转动设备，且无监护人员，一旦发生事故难以及时救援。处置建议：立即制止并带离该人员，进行安全教育并记录；重申厂内通行规定与考核要求；必要时通知厂方安全部门；班组长应检查是否因通道设置不合理导致绕行不便，从管理上予以改善。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '班组进行管道保温作业时，附近管廊正进行焊接动火作业，火星不断落下。请指出风险与正确做法。', '', '风险：落下的火花可能引燃保温材料、涂料稀释剂等可燃物，也可能烫伤人员，两处作业存在交叉干扰。正确做法：立即停止本班组作业并向现场安全员报告；明确交叉作业的隔离与防护措施（加设接火盘、防火毯、错时作业与专人监护）；确认上方动火已落实防火措施并经许可后，方可恢复作业。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '一名工人佩戴的是已经破损的安全帽，班组长要求更换，工人认为“还能戴”。请说明为什么必须更换。', '', '安全帽依靠帽壳与帽衬的完好结构吸收和分散冲击能量，出现裂纹、老化、变形或帽衬断裂后防护能力显著下降，外观正常也可能在受冲击时失效；因此按标准要求，破损、超期（一般塑料帽不超过两年半）或已受冲击的安全帽必须立即更换，不得继续使用。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '夏季高温作业时，一名员工出现头晕、恶心、大量出汗的症状。请分析原因并说明现场处置措施。', '', '原因：高温环境下长时间作业导致热应激，属中暑先兆。处置：立即停止作业，将人员转移到阴凉通风处休息，解开衣领、补充含盐清凉饮料或淡盐水，用湿毛巾降温；症状不能缓解时立即送医；后续应调整作业时间（避开高温时段）、增加轮换与补水、加强现场防暑物资保障。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某项目在未办理受限空间作业许可的情况下，安排一名工人进入储罐内进行涂层修补，且罐外无人监护。请从安全管理角度全面分析问题。', '', '该安排违反多项强制规定：①未办理受限空间作业许可，无审批与风险辨识；②未进行气体检测，无法确认含氧量、可燃与有毒气体是否合格；③未采取强制通风措施；④无专人监护，一旦发生昏迷无人及时发现与救援；⑤单人作业缺少互助。整体属于违章指挥与违章作业，一旦发生事故极易造成人员伤亡。正确做法：停止作业；按“先通风、再检测、后作业”和“四不进入”要求完善审批、检测、通风、监护与应急措施，作业人员与监护人经培训并落实防护装备后方可入内作业。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '喷砂除锈的主要目的是？', '[{"key": "A", "text": "清除氧化皮、铁锈等污物并使表面形成一定粗糙度"}, {"key": "B", "text": "增加钢材厚度"}, {"key": "C", "text": "提高钢材导电性"}, {"key": "D", "text": "使表面更光滑"}]', 'A', '除锈兼有清洁与造粗糙度双重目的，粗糙度直接影响涂层附着力。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '喷射除锈等级 Sa2.5 表示的是？', '[{"key": "A", "text": "非常彻底的喷射清理"}, {"key": "B", "text": "轻度喷射清理"}, {"key": "C", "text": "手工与动力工具除锈"}, {"key": "D", "text": "火焰除锈"}]', 'A', 'Sa2.5 要求表面无可见油脂、污垢、氧化皮、铁锈与旧漆层，仅允许轻微残留痕迹。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '喷砂磨料在作业中起到的作用是？', '[{"key": "A", "text": "高速冲击去除锈层并形成锚纹（粗糙度）"}, {"key": "B", "text": "对钢材起防腐作用"}, {"key": "C", "text": "充当涂层粘接剂"}, {"key": "D", "text": "起保温隔热作用"}]', 'A', '磨料靠动能冲击与切削作用去除锈层并形成锚纹。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '下列属于常用金属磨料的是？', '[{"key": "A", "text": "钢丸、钢砂"}, {"key": "B", "text": "木屑"}, {"key": "C", "text": "塑料颗粒"}, {"key": "D", "text": "纸屑"}]', 'A', '钢丸、钢砂可循环使用、粉尘少，是常用金属磨料。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '喷砂用压缩空气的基本要求是？', '[{"key": "A", "text": "干燥、无油、洁净"}, {"key": "B", "text": "含少量水便于降温"}, {"key": "C", "text": "含油以润滑机具"}, {"key": "D", "text": "温度越低越好"}]', 'A', '压缩空气含油含水会污染基材、显著降低涂层附着力。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '喷砂作业人员必须配备的防护装备是？', '[{"key": "A", "text": "喷砂防护服与供气式（或符合要求的）呼吸防护、防护面罩"}, {"key": "B", "text": "仅普通棉纱口罩"}, {"key": "C", "text": "仅安全帽"}, {"key": "D", "text": "无特殊要求"}]', 'A', '喷砂粉尘危害大，必须配备整体防护与呼吸防护。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '喷嘴磨损严重时应及时更换，原因是？', '[{"key": "A", "text": "影响喷射效率与除锈质量的均匀性"}, {"key": "B", "text": "只影响设备外观"}, {"key": "C", "text": "除噪声外无其他影响"}, {"key": "D", "text": "会使磨料粒度变粗"}]', 'A', '喷嘴孔磨损后气流与磨料轨迹改变，除锈效率下降且不均匀。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '与喷砂相比，抛丸除锈的主要优点之一是？', '[{"key": "A", "text": "磨料可循环使用、粉尘相对较少、效率高"}, {"key": "B", "text": "完全不需要除尘系统"}, {"key": "C", "text": "无需任何设备维护"}, {"key": "D", "text": "适用于任意复杂形状工件"}]', 'A', '抛丸靠机械离心抛射，磨料循环使用，但对形状复杂的死角适应性较差。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '喷砂作业时喷枪与工件表面的合理角度一般为？', '[{"key": "A", "text": "约 75°～90°，可略带倾角"}, {"key": "B", "text": "与表面平行（0°）"}, {"key": "C", "text": "从背面 180° 喷射"}, {"key": "D", "text": "任意角度均无差别"}]', 'A', '接近垂直并略带倾角可兼顾效率与表面均匀性，过大角度易造成磨料反弹伤人。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '喷砂合格的钢材表面出现返锈时，正确处理是？', '[{"key": "A", "text": "在返锈发生前及时涂装，已返锈的须重新处理"}, {"key": "B", "text": "直接涂面漆覆盖"}, {"key": "C", "text": "喷水冲洗后直接涂装"}, {"key": "D", "text": "不做任何处理"}]', 'A', '返锈会破坏锚纹与清洁度，须重新处理合格后方可涂装。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '影响喷砂除锈质量的主要因素有？', '[{"key": "A", "text": "压缩空气压力与流量"}, {"key": "B", "text": "磨料种类与粒度"}, {"key": "C", "text": "喷嘴距离、角度与移动速度"}, {"key": "D", "text": "钢材本身的颜色"}]', 'A,B,C', '除锈质量取决于工艺参数组合，与钢材颜色无关。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '喷砂作业的主要职业危害包括？', '[{"key": "A", "text": "粉尘（尤其含游离二氧化硅）"}, {"key": "B", "text": "噪声与振动"}, {"key": "C", "text": "高速磨料与飞溅物造成的机械伤害"}, {"key": "D", "text": "电磁辐射"}]', 'A,B,C', '喷砂为粉尘、噪声与机械伤害高风险作业，不含电磁辐射危害。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '喷砂机具日常维护内容通常包括？', '[{"key": "A", "text": "检查空压机与油水分离器"}, {"key": "B", "text": "检查喷嘴磨损与管路泄漏"}, {"key": "C", "text": "清理集尘与料仓系统"}, {"key": "D", "text": "给工件表面喷涂面漆"}]', 'A,B,C', '喷涂面漆属下一道工序，不属于喷砂机具维护内容。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '关于磨料选择，下列说法正确的有？', '[{"key": "A", "text": "根据钢材表面状况与粗糙度要求选择"}, {"key": "B", "text": "钢丸、钢砂、铜矿渣等为常用磨料"}, {"key": "C", "text": "石英砂因游离二氧化硅危害应限制使用"}, {"key": "D", "text": "磨料越细除锈效率越高"}]', 'A,B,C', '磨料粒度越大，切削能力与粗糙度越大，效率通常更高，并非越细越好。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '抛丸设备的典型组成部分包括？', '[{"key": "A", "text": "抛丸器（叶轮）"}, {"key": "B", "text": "丸料循环与分离系统"}, {"key": "C", "text": "除尘系统"}, {"key": "D", "text": "面漆喷涂装置"}]', 'A,B,C', '抛丸设备由抛丸、循环分离与除尘等系统组成，不含喷涂装置。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '喷砂除锈合格后应在返锈前及时涂装。', '', '对', '暴露时间过长会返锈，影响附着力。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '压缩空气含水含油对涂层附着力没有影响。', '', '错', '油水污染基材是附着力不良的常见原因。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, 'Sa2.5 级要求表面无可见油脂、污垢、氧化皮、铁锈与旧漆层。', '', '对', '这是 Sa2.5 的定义性要求。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '喷砂作业人员可以不佩戴呼吸防护用品。', '', '错', '粉尘危害严重，必须佩戴合格呼吸防护。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '抛丸作业使用的钢丸可以循环使用。', '', '对', '丸料经分离除尘后可循环使用，是其优点之一。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '喷嘴磨损对除锈效率和均匀性没有影响。', '', '错', '喷嘴磨损会改变喷射轨迹，显著影响效率与质量。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '喷砂可用于去除旧漆层与氧化皮。', '', '对', '喷砂既可除锈也可清除旧涂层。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '磨料粒度越粗，形成的表面粗糙度通常越大。', '', '对', '粒度与粗糙度正相关，需与涂层体系匹配。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '喷砂粉尘不会造成职业危害。', '', '错', '粉尘是喷砂最主要的职业危害之一。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '除锈等级不达标时，可依靠增加涂层厚度来弥补。', '', '错', '底材处理不达标是附着力失效的根源，无法靠厚度弥补。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述喷砂除锈的工艺流程与关键控制点。', '', '流程：表面预清理（除油污、焊渣）→ 检查压缩空气（干燥无油）→ 调整压力与磨料→ 按顺序喷砂至规定除锈等级 → 清除表面粉尘 → 检验等级与粗糙度 → 在返锈前完成底漆涂装。关键控制点：压缩空气质量、磨料选择与消耗、喷距与角度、除锈等级与粗糙度、环境湿度与露点、涂装间隔时间。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '为什么喷砂用压缩空气必须干燥无油？应如何处理？', '', '压缩空气中的水和油会在钢材表面形成薄膜，隔绝涂层与基材的结合，导致附着力下降、起泡与早期剥落。处理措施：空压机后设置油水分离器、冷干机与精密过滤器；定期排放储气罐与管路积水；定时检查过滤元件并及时更换；作业前用白布对着气流吹扫进行检查。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '喷砂作业应落实哪些安全防护措施？', '', '①作业人员穿专用喷砂防护服、佩戴供气式或符合要求的呼吸防护与防护面罩；②设置隔离区域与警示标识，禁止无关人员进入；③作业区强制通风、配备除尘设备；④检查高压管路与接头完好，喷枪严禁对人；⑤作业人员定期体检，控制连续作业时间；⑥配备急停与应急联络措施。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述抛丸设备的组成与工作原理。', '', '抛丸设备主要由抛丸器（高速旋转叶轮）、丸料输送与循环系统、丸渣分离器、除尘系统与工件输送装置组成。工作原理：叶轮高速旋转将钢丸加速抛出，冲击工件表面去除氧化皮与锈层并形成粗糙度；丸料与锈渣混合物经分离器分离后，合格钢丸循环使用，粉尘由除尘系统收集。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '除锈质量不合格常见表现及处置方法有哪些？', '', '常见表现：仍可见氧化皮或锈斑、粗糙度不足或过深、表面有油污粉尘、出现返锈。处置：查明原因（压力不足、磨料失效、压缩空气含油水、暴露时间过长等）后重新处理；局部不合格部位应补喷；已返锈的须整体重新除锈；重新检验合格并及时涂装底漆。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某项目喷砂合格的钢管第二天表面出现大面积返锈，需重新处理。请分析原因并提出预防措施。', '', '原因：①喷砂后未在允许时间内涂装，暴露于高湿或有腐蚀性大气中；②夜间温差导致结露；③除锈后未清除表面粉尘与盐分；④现场靠近酸性或含盐雾环境。预防措施：喷砂与涂装工序紧密衔接，控制在 4 小时内完成底漆涂装；夜间或高湿天气加强遮盖与除湿；喷砂后彻底吹扫除尘；必要时采用临时防锈措施（如可焊车间漆）。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某批管道涂层成片剥落，怀疑与喷砂环节有关。请列出排查思路。', '', '排查思路：①核对除锈等级与粗糙度是否符合要求（比对标准照片与粗糙度仪）；②检查压缩空气是否含油含水（白布吹扫试验、检查油水分离器与冷干机）；③检查表面是否残留油污、粉尘或盐分；④核对喷砂后到涂装的间隔时间是否过长导致返锈；⑤取样做附着力试验（拉拔或划格）验证，确定失效界面在基材与底漆之间还是涂层内部，并据此判定责任环节。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '喷砂作业区粉尘弥漫，多名工人出现咳嗽、咽部不适。请说明整改措施。', '', '整改措施：①立即加强通风与除尘，检查除尘设备是否正常运行；②更换或补充合格呼吸防护用品并强制佩戴；③检查磨料是否含过量易破碎成分，优先选用低粉尘磨料；④湿式或半湿式喷砂可优先考虑；⑤设置隔离与警示，控制无关人员进入；⑥安排作业人员轮换与职业健康体检，建立粉尘作业健康监护记录。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '抛丸机丸渣分离器效率下降，磨料中混入大量粉尘与碎屑，会给施工质量带来什么影响？如何处理？', '', '影响：①粉尘随磨料冲击工件，造成表面二次污染，降低涂层附着力；②碎屑使粗糙度不均匀；③粉尘浓度升高，加剧除尘负荷与职业危害；④丸料消耗增大、效率下降。处理：停机检查分离器风量、风道与挡板是否堵塞或磨损；清理与调整分离器参数；更换磨损部件；检查除尘系统风量与滤芯；恢复后取样检验丸料清洁度与除锈质量。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '管道内壁喷砂时，管端与焊缝处难以达到规定的除锈等级。请提出解决方案。', '', '解决方案：①改用适配内壁的小型旋转喷头或长杆喷枪，保证可达性；②调整喷嘴角度与距离，必要时增加辅助照明与内窥检查；③对死角与焊缝采用动力工具（砂轮机、钢丝刷）补除锈，达到 St3 或业主要求等级；④控制磨料粒度，避免粗磨料卡滞；⑤加强过程检查与验收，对无法达标的部位与设计、监理确认处理方案后再涂装。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '双组分涂料使用前的正确做法是？', '[{"key": "A", "text": "按产品说明书规定的比例混合主剂与固化剂并充分搅拌"}, {"key": "B", "text": "只取主剂单独使用"}, {"key": "C", "text": "随意按体积估量混合"}, {"key": "D", "text": "先加固化剂后长期放置"}]', 'A', '配比准确、搅拌充分是双组分涂料正常固化的前提。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '涂料术语中的“适用期（pot life）”指的是？', '[{"key": "A", "text": "两组分混合后允许使用的最长时间"}, {"key": "B", "text": "涂料未开封的保质期"}, {"key": "C", "text": "涂装后的干燥时间"}, {"key": "D", "text": "涂料的储存温度上限"}]', 'A', '适用期从混合完成时开始计时，超过后涂料性能下降直至报废。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '稀释剂的加入量应如何控制？', '[{"key": "A", "text": "严格按产品说明书的推荐范围，并结合喷涂方式调整"}, {"key": "B", "text": "越多越好，便于施工"}, {"key": "C", "text": "凭手感随意添加"}, {"key": "D", "text": "任何情况下都不允许添加"}]', 'A', '过量稀释会导致流挂、遮盖力下降与固化不良。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '双组分涂料混合后静置一段时间的目的主要是？', '[{"key": "A", "text": "使两组分反应熟化（诱导期），减少气泡与局部固化不良"}, {"key": "B", "text": "让其变稠"}, {"key": "C", "text": "加快溶剂挥发"}, {"key": "D", "text": "降低涂料温度"}]', 'A', '熟化有利于组分充分反应、气泡逸出，提高涂膜质量。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '施工现场测定涂料粘度常用的是？', '[{"key": "A", "text": "涂-4 杯流出时间法"}, {"key": "B", "text": "天平称重法"}, {"key": "C", "text": "温度计测量法"}, {"key": "D", "text": "湿膜卡测量法"}]', 'A', '涂-4 杯是现场常用的粘度测定器具；湿膜卡用于测湿膜厚度。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '环境温度过低时，涂料的状态通常是？', '[{"key": "A", "text": "干燥固化变慢，适用期相应延长"}, {"key": "B", "text": "干燥明显加快"}, {"key": "C", "text": "性能完全不受影响"}, {"key": "D", "text": "涂料自行变稀"}]', 'A', '低温抑制固化反应，干燥变慢、适用期延长，但涂膜质量可能下降。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '环境温度过高时，双组分涂料的适用期会？', '[{"key": "A", "text": "明显缩短"}, {"key": "B", "text": "明显延长"}, {"key": "C", "text": "保持不变"}, {"key": "D", "text": "不确定且无影响"}]', 'A', '高温加速固化反应，适用期缩短，需减少每次调配量。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '调配时先加主剂、再按比例加入固化剂并搅拌，主要目的是？', '[{"key": "A", "text": "保证混合均匀，避免局部固化不良"}, {"key": "B", "text": "节省搅拌时间"}, {"key": "C", "text": "减少气味散发"}, {"key": "D", "text": "便于清洗容器"}]', 'A', '若先加固化剂或搅拌不充分，易出现局部未固化、涂膜发软等问题。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '稀释剂选型错误可能导致下列哪种后果？', '[{"key": "A", "text": "溶解力不足引起涂膜发白、橘皮、附着力差"}, {"key": "B", "text": "提高涂层附着力"}, {"key": "C", "text": "加快涂膜干燥"}, {"key": "D", "text": "提高耐候性"}]', 'A', '稀释剂必须与涂料体系配套，否则破坏涂膜形成过程。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '已超过适用期的混合涂料应如何处理？', '[{"key": "A", "text": "废弃处理，不得继续使用"}, {"key": "B", "text": "加稀释剂继续使用"}, {"key": "C", "text": "补加主剂后继续使用"}, {"key": "D", "text": "静置一段时间再用"}]', 'A', '超期涂料已发生交联，继续使用会造成涂膜质量缺陷，须按规定废弃。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '影响涂料适用期长短的因素有哪些？', '[{"key": "A", "text": "环境温度"}, {"key": "B", "text": "单次混合量大小"}, {"key": "C", "text": "涂料品种与配方"}, {"key": "D", "text": "盛装容器的外观颜色"}]', 'A,B,C', '温度、混合量（放热）与涂料体系决定适用期，与容器颜色无关。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '涂料调配的正确做法包括？', '[{"key": "A", "text": "核对双组分名称与配比"}, {"key": "B", "text": "使用干净、专用容器与搅拌工具"}, {"key": "C", "text": "按说明书规定加入稀释剂"}, {"key": "D", "text": "凭经验目测配比"}]', 'A,B,C', '目测配比会造成配比失准，属错误做法。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '涂料调配环节常见的质量问题有？', '[{"key": "A", "text": "配比错误导致固化不良"}, {"key": "B", "text": "稀释过度造成流挂与遮盖力不足"}, {"key": "C", "text": "搅拌不均产生涂料疙瘩"}, {"key": "D", "text": "器具混用引入杂质"}]', 'A,B,C,D', '四项均会在调配环节引入质量缺陷，器具混用也会污染涂料。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '双组分涂料使用过程中应注意？', '[{"key": "A", "text": "记录混合起始时间"}, {"key": "B", "text": "在适用期内用完"}, {"key": "C", "text": "观察粘度变化并合理安排施工节奏"}, {"key": "D", "text": "超过适用期后加水继续使用"}]', 'A,B,C', '超期后加水会破坏体系，必须废弃。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '使用稀释剂时应遵守？', '[{"key": "A", "text": "选用涂料配套稀释剂"}, {"key": "B", "text": "严格控制加入量"}, {"key": "C", "text": "加强通风、严禁烟火"}, {"key": "D", "text": "用手直接接触以感知稀稠"}]', 'A,B,C', '稀释剂多为易燃有毒溶剂，严禁皮肤直接接触。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '双组分涂料可以只使用主剂而不加固化剂。', '', '错', '不加固化剂无法交联固化，涂膜不会形成性能。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '适用期指涂料混合后允许使用的最长时间。', '', '对', '适用期从混合完成起计算。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '稀释剂可以随意多加，不会影响涂膜质量。', '', '错', '过量稀释会造成流挂、遮盖力下降与固化不良。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '环境温度越高，双组分涂料的适用期越短。', '', '对', '高温加速反应，适用期缩短。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '混合后静置熟化一段时间有利于减少气泡。', '', '对', '熟化使反应充分、气泡逸出。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '过了适用期的涂料可以通过加稀释剂继续使用。', '', '错', '超期涂料已交联，加稀释剂也无法恢复性能。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '涂料调配应在通风良好、远离火源处进行。', '', '对', '溶剂挥发易燃有毒，须通风防火。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '涂-4 杯可用于现场测定涂料粘度。', '', '对', '涂-4 杯是现场常用的粘度测定器具。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '不同厂家的稀释剂可以随意混用且没有影响。', '', '错', '不同体系稀释剂混用可能破坏溶解平衡，引起涂膜缺陷。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '配比错误会导致涂层固化不良和附着力下降。', '', '对', '配比是双组分涂料固化的关键参数。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述双组分涂料的调配流程与注意事项。', '', '流程：核对涂料与固化剂名称、批号与配比 → 搅拌均匀主剂 → 按比例准确称量加入固化剂 → 充分搅拌（注意桶壁与桶底）→ 按说明加入稀释剂调整粘度 → 静置熟化 → 过滤后使用。注意事项：严格执行配比、使用专用干净容器、记录混合时间、控制单次调配量以适应现场进度、调配区通风防火。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '什么是适用期？哪些因素会影响适用期长度？', '', '适用期是双组分涂料混合后保持可使用状态的最长时间，超过后涂料粘度上升直至胶化报废。影响因素：环境温度（温度越高越短）、单次混合量（量大放热快、适用期更短）、涂料品种与配方、容器散热条件。施工时应据此控制单次调配量，做到用多少调多少。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '稀释剂使用不当可能引起哪些涂膜缺陷？', '', '①溶解力不足或选型错误：涂膜发白、橘皮、附着力下降；②过量稀释：流挂、遮盖力不足、涂层薄且针孔；③使用快干稀释剂且挥发过快：涂膜表面结皮、内部溶剂残留起泡；④混用不配套稀释剂：涂料絮凝、颜料沉淀。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '涂料调配现场的安全与环保要求有哪些？', '', '①在通风良好、远离火源处调配，严禁吸烟与动火；②配备灭火器材与防静电措施；③作业人员佩戴防护手套、护目镜与防毒口罩，避免皮肤直接接触；④废稀释剂、清洗废液与空桶按规定收集，不得随地倾倒或排入下水；⑤容器加盖、及时清理洒落涂料，保持现场整洁。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '如何判断涂料已超过适用期？超过适用期后应如何处理？', '', '判断方法：目视粘度明显上升、搅拌有拉丝或结块、涂装时雾化困难、遮盖异常。处理：立即停止使用并按规定作为危险废物收集处置，严禁加入稀释剂或主剂继续使用，也不得掺入新料。同时应复盘每次调配量是否过大、环境温度是否过高，调整后续施工组织。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某批涂层施工后一周仍发软发粘、不固化。请分析可能原因并给出处理意见。', '', '可能原因：①主剂与固化剂配比错误（固化剂偏少）；②搅拌不充分造成局部未固化；③错用稀释剂或稀释剂含水；④环境温度过低导致固化反应未进行；⑤涂料超过适用期或被污染。处理意见：现场取样判断固化程度，判定为固化不良的部位应全部铲除并按正确配比重新涂装；同时核对配比记录、搅拌方式与温度条件，明确整改措施并加强过程监督。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '夏季高温时段调配的涂料在桶内很快变稠结块，无法正常喷涂。请提出改进措施。', '', '改进措施：①减少单次调配量，做到随用随配；②将涂料与固化剂提前存放在阴凉处，降低初始温度；③避开正午高温时段调配与施工，安排早晚作业；④采用冷水浴或专用冷却措施延缓反应；⑤增设调配记录与检查，明确超过适用期的处理规定，杜绝勉强使用。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '喷涂后涂膜出现发白、橘皮。请从涂料调配角度分析原因。', '', '调配角度原因：①稀释剂选型错误（溶解力不足）或使用快干型稀释剂，涂膜表干过快、内部溶剂残留；②稀释比例过大导致成膜物质不足；③稀释剂含水或容器内有残留水分；④涂料存放不当造成颜料絮凝。处理：核对并更换配套稀释剂、按推荐比例稀释、避免低温高湿环境施工、铲除严重发白涂层重新涂装，并加强调配过程的记录与复核。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '调配人员未按比例称量、凭经验估量，导致整批涂层附着力差并出现返工。作为技术人员你如何整改？', '', '整改措施：①立即停止该批涂料使用，对已施工部位进行附着力检测并返工；②配发经校准的称量器具（电子秤、量杯）并强制使用；③在调配区张贴配比卡与操作步骤，明确主剂/固化剂比例与稀释上限；④实行调配人签字与班组长复核的双人确认；⑤开展专项培训与考核，将该环节纳入质量检查要点，防止再次发生。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '冬季低温环境下涂料干燥缓慢，影响整体工期。请提出可行的技术与管理措施。', '', '技术措施：①选用低温型或冬用型涂料体系（经设计与监理同意）；②搭设保温棚、使用加热设备提升环境温度至产品规定范围；③对工件表面进行预热，确保表面温度高于露点 3℃ 以上；④适当减少稀释剂用量，避免过度稀释；⑤严禁用明火直接加热涂料桶。管理措施：调整工序计划、增加养护时间、加强温度与湿度记录，并与业主沟通工期节点。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '高压无气喷涂的雾化原理是？', '[{"key": "A", "text": "涂料加压至高压后经小孔径喷嘴释放，靠压力骤降实现雾化"}, {"key": "B", "text": "利用压缩空气吹散涂料"}, {"key": "C", "text": "靠刷子涂抹成膜"}, {"key": "D", "text": "靠静电场吸附成膜"}]', 'A', '无气喷涂靠液压雾化，不需压缩空气参与分散。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '与空气喷涂相比，高压无气喷涂的主要优点是？', '[{"key": "A", "text": "效率高、涂层致密、涂料飞散少、可喷高粘度涂料"}, {"key": "B", "text": "涂料利用率极低"}, {"key": "C", "text": "涂层疏松多孔"}, {"key": "D", "text": "仅适合小面积施工"}]', 'A', '无气喷涂涂料利用率高、膜厚易达标，适合大面积施工。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '选择喷嘴时应主要依据？', '[{"key": "A", "text": "涂料类型与粘度、所需湿膜厚度"}, {"key": "B", "text": "设备外壳颜色"}, {"key": "C", "text": "操作人员身高"}, {"key": "D", "text": "现场光照强度"}]', 'A', '喷嘴孔径与流量决定出漆量，须与涂料粘度及膜厚要求匹配。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '喷涂作业时的喷距一般控制在？', '[{"key": "A", "text": "约 25～40 cm"}, {"key": "B", "text": "5 cm"}, {"key": "C", "text": "100 cm 以上"}, {"key": "D", "text": "距离不影响质量"}]', 'A', '距离过近易流挂，过远易干喷，须按产品与喷嘴要求控制。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '走枪时应保持的基本动作是？', '[{"key": "A", "text": "匀速、平行于工件表面移动"}, {"key": "B", "text": "忽快忽慢以求覆盖"}, {"key": "C", "text": "以腕部大幅摆动"}, {"key": "D", "text": "定点喷涂某一处"}]', 'A', '匀速平行走枪是保证涂层厚度均匀的关键。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '相邻喷涂道之间的搭接量一般控制在？', '[{"key": "A", "text": "约 1/3～1/2 幅宽"}, {"key": "B", "text": "完全不搭接"}, {"key": "C", "text": "完全重合"}, {"key": "D", "text": "任意即可"}]', 'A', '适当搭接可避免漏喷与道间色差。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '喷枪工作压力过低会造成？', '[{"key": "A", "text": "雾化不良、涂膜厚薄不均、易出现流挂或干喷"}, {"key": "B", "text": "涂层更加致密"}, {"key": "C", "text": "施工效率提高"}, {"key": "D", "text": "对质量无明显影响"}]', 'A', '压力不足无法有效雾化，直接影响涂膜外观与均匀性。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '高压无气喷涂设备的核心组成不包括下列哪项？', '[{"key": "A", "text": "高压泵、蓄压器、高压软管与喷枪属于其组成"}, {"key": "B", "text": "（不属于）空气压缩机的雾化喷枪"}, {"key": "C", "text": "（不属于）刷涂滚筒"}, {"key": "D", "text": "（不属于）抹子"}]', 'B', '标准配置含高压泵、蓄压器、高压软管与喷枪；气动雾化喷枪属空气喷涂设备。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '高压无气喷涂作业中最典型的安全风险是？', '[{"key": "A", "text": "高压涂料射流刺入皮肤造成组织损伤，以及溶剂中毒与火灾"}, {"key": "B", "text": "冻伤"}, {"key": "C", "text": "溺水"}, {"key": "D", "text": "核辐射"}]', 'A', '高压射流可穿透皮肤，属严重伤害，严禁喷枪对人。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '喷涂作业结束后应立即进行的工作是？', '[{"key": "A", "text": "用配套清洗剂清洗管路、喷枪与喷嘴"}, {"key": "B", "text": "直接放置待下次使用"}, {"key": "C", "text": "用清水冲洗所有溶剂型涂料"}, {"key": "D", "text": "拆解设备长期存放"}]', 'A', '及时清洗可防止涂料固化堵塞管路与喷嘴。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '影响高压无气喷涂雾化效果的因素有？', '[{"key": "A", "text": "涂料粘度"}, {"key": "B", "text": "喷嘴孔径"}, {"key": "C", "text": "喷涂压力"}, {"key": "D", "text": "车间照明亮度"}]', 'A,B,C', '雾化效果由涂料、喷嘴与压力三者匹配决定，与照明无关。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '无气喷涂常见的涂膜缺陷有？', '[{"key": "A", "text": "干喷（飞漆）"}, {"key": "B", "text": "流挂"}, {"key": "C", "text": "橘皮"}, {"key": "D", "text": "涂层过厚导致开裂"}]', 'A,B,C,D', '四项均可能在无气喷涂中出现，需通过参数与操作控制避免。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '喷涂作业的安全防护要求包括？', '[{"key": "A", "text": "佩戴防毒面具、防护眼镜与防护手套"}, {"key": "B", "text": "作业区加强通风"}, {"key": "C", "text": "严禁烟火并做好防静电"}, {"key": "D", "text": "废清洗剂随地倾倒"}]', 'A,B,C', '废溶剂属危险废物，必须按规定收集处置。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '无气喷涂设备日常维护内容包括？', '[{"key": "A", "text": "检查高压软管与接头有无渗漏、鼓包"}, {"key": "B", "text": "清洗过滤器与喷嘴"}, {"key": "C", "text": "检查泵体密封与液压油状态"}, {"key": "D", "text": "用尖锐金属丝反复捅洗喷嘴"}]', 'A,B,C', '用金属丝捅喷嘴会损伤孔型，应使用溶剂浸泡或专用工具。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '关于喷嘴使用，正确的做法有？', '[{"key": "A", "text": "磨损后及时更换以保证雾化质量"}, {"key": "B", "text": "按涂料类型选择对应孔径"}, {"key": "C", "text": "堵塞时浸泡溶剂或用专用工具清理"}, {"key": "D", "text": "用铁丝反复捅洗以疏通"}]', 'A,B,C', '铁丝会扩大或损伤喷嘴孔径，属错误做法。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '高压无气喷涂依靠压缩空气将涂料吹散成雾。', '', '错', '无气喷涂靠液压雾化，不需要压缩空气分散涂料。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '喷距越近，涂层质量越好。', '', '错', '喷距过近易造成流挂，须按规范控制距离。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '无气喷涂的涂料利用率通常高于空气喷涂。', '', '对', '无气喷涂飞散少，利用率更高。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '高压涂料射流可能刺穿皮肤，喷枪严禁对人。', '', '对', '这是无气喷涂最重要的安全禁令之一。', 1, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '走枪速度忽快忽慢会造成涂层厚薄不均。', '', '对', '涂层厚度与走枪速度直接相关。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '喷枪压力越低，涂层越致密。', '', '错', '压力不足会导致雾化不良、涂层疏松不均。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '喷嘴堵塞时可用金属丝用力捅洗。', '', '错', '金属丝会损伤喷嘴孔型，应浸泡溶剂或用专用通针清理。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '相邻喷涂道之间应保持适当搭接以保证连续覆盖。', '', '对', '搭接不足会产生漏喷条带。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '溶剂型涂料喷涂现场必须严禁烟火并保持通风。', '', '对', '溶剂挥发易燃有毒，须防火防中毒。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '喷涂结束后管路与喷嘴无需清洗。', '', '错', '涂料固化后会堵塞管路与喷嘴，必须及时清洗。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述高压无气喷涂的工作原理与主要优点。', '', '工作原理：高压泵将涂料加压至 15～40 MPa 甚至更高，经高压软管送至喷枪，涂料通过小孔径喷嘴时压力骤降并高速喷出，靠自身动能雾化成膜。主要优点：单道成膜厚、施工效率高、涂料利用率高（飞散少）、可喷涂高粘度涂料、涂层致密，适用于大面积钢结构与管道防腐施工。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '如何正确选择喷嘴并设定喷涂压力？', '', '选择喷嘴：根据涂料粘度与所需膜厚选择孔径与流量，一般高粘度或厚膜选大孔径；核对喷嘴扇幅与施工部位匹配。设定压力：先在推荐压力范围内试喷，以雾化均匀、扇形饱满、无干喷或流挂为原则，采用最小可行压力以延长设备寿命；压力随喷嘴磨损适当上调，但不得超过设备与软管额定值。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '无气喷涂产生“干喷”（飞漆）的原因及预防措施有哪些？', '', '原因：①喷距过远；②环境温度高、风速大导致溶剂挥发过快；③压力过高或喷嘴孔径偏小；④涂料粘度过高；⑤走枪速度过快。预防措施：按规范控制喷距（约 25～40 cm）；调整压力与喷嘴匹配；适当加入配套稀释剂降低粘度；在避风或有遮挡条件下作业；保持均匀适中的走枪速度。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '高压无气喷涂作业应落实哪些安全防护措施？', '', '①作业人员佩戴防毒面具、防护眼镜、防护手套与工作服，防止溶剂中毒与皮肤接触；②严禁将喷枪对准人体，清洗或检查喷嘴前先卸压；③定期检查高压软管、接头与密封件，防止爆管；④作业区强制通风、严禁烟火、做好防静电与接地；⑤配备灭火器材；⑥废溶剂与清洗液按规定收集处置，避免环境污染。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '喷涂作业结束后，设备应如何清洗与保养？', '', '①停机卸压后拆下喷嘴单独浸泡于配套溶剂中，用专用通针或软刷清理；②将吸料管插入清洗溶剂，循环冲洗管路与泵体直至出液干净；③拆卸过滤器清洗滤网；④擦净设备外部，检查软管、接头与密封件有无磨损渗漏；⑤对泵体运动部件按要求加注润滑油；⑥将设备存放在干燥处，长期不用时防锈保养并定期试运转。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某段管道喷涂后出现明显流挂，请分析原因并提出纠正措施。', '', '原因：①单道涂层过厚或走枪速度过慢；②喷距过近；③稀释过度导致粘度偏低；④喷嘴孔径过大出漆量偏高；⑤工件表面残留油污或温度过高。纠正措施：把流挂部位铲除或打磨平整后重涂；调整喷距、走枪速度与压力，控制单道湿膜厚度不超过推荐值；按说明书调整稀释比例；检查并更换合适喷嘴；作业前确认表面清洁与工件温度适宜。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '涂层表面出现明显粗糙颗粒与干喷痕迹，请列出排查步骤。', '', '排查步骤：①检查喷距是否过远、风速是否过大（改善作业环境）；②核对涂料粘度是否偏高（按规定稀释至工艺范围）；③检查喷嘴是否磨损或半堵塞（清洗或更换喷嘴）；④核对喷涂压力是否合适（调整至推荐区间）；⑤检查涂料是否搅拌不均或混入杂质（重新过滤搅拌）；⑥确认走枪速度是否过快并予以纠正。处理：缺陷部位打磨平滑后补涂。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '高压软管在使用中突然破裂，涂料高压喷出。请说明风险与预防措施。', '', '风险：高压涂料射流可能刺穿皮肤造成严重组织损伤甚至危及生命；同时涂料飞溅污染环境、溶剂挥发存在火灾与中毒风险。预防措施：①定期检查软管外观有无鼓包、磨损、老化并按周期强制更换；②接头连接牢固、无渗漏，严禁超压使用；③喷枪及各接头与人员保持安全距离，严禁对人；④作业前进行低压试运行检查；⑤操作人员佩戴防护装备并了解应急处置方法，一旦发生刺伤应立即就医，不得自行处理。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '大面积喷涂后检测发现涂层厚度不均，局部低于设计要求。请分析原因并给出处理办法。', '', '原因：①走枪速度与搭接不均匀；②喷距变化、手法不稳定；③单道厚度设计与实际不符，道数不足；④喷涂压力波动或喷嘴部分堵塞导致出漆量不稳定；⑤复杂部位（边角、焊缝）未加强补喷。处理办法：在合格区域内按比例抽查，对低于设计厚度的部位打磨清洁后补涂至合格；对边角与焊缝等部位制定加强涂装要求；随后优化操作规范（固定喷距与走枪速度、控制搭接 1/3～1/2 幅宽），加强过程厚度检测并留存记录。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '喷涂作业中一名工人出现头晕、恶心症状。请说明应急处置与后续整改。', '', '应急处置：立即停止作业、将人员撤离至通风良好处并解开衣领、保持呼吸道通畅；症状明显或持续加重时立即送医并报告现场负责人；同时检查作业区通风、防毒面具是否失效、涂料溶剂浓度是否超标。后续整改：加强机械通风与局部排风；检查并更换合格的呼吸防护用品，强制正确佩戴；控制连续作业时间并安排轮换；密封盛装涂料容器减少挥发；建立溶剂中毒应急演练与健康监护制度。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '涂层出现明显“流挂”的主要原因是？', '[{"key": "A", "text": "单道涂装过厚、稀释过度或喷距过近"}, {"key": "B", "text": "表面粗糙度过大"}, {"key": "C", "text": "涂料粘度过高"}, {"key": "D", "text": "环境过于干燥"}]', 'A', '流挂本质是湿膜在固化前因自重流动，与膜厚、粘度、喷距直接相关。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '涂层“针孔”最主要的危害是？', '[{"key": "A", "text": "形成贯穿通道使腐蚀介质直达基材，引起点蚀"}, {"key": "B", "text": "仅影响外观颜色"}, {"key": "C", "text": "增加涂层厚度"}, {"key": "D", "text": "提高附着力"}]', 'A', '针孔是防腐涂层最危险的缺陷之一，是腐蚀的起始点。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '涂层“起泡（鼓泡）”最常与下列哪项有关？', '[{"key": "A", "text": "基材表面残留油污水盐，或涂层间溶剂残留未挥发"}, {"key": "B", "text": "涂料颜色偏差"}, {"key": "C", "text": "涂层厚度偏薄"}, {"key": "D", "text": "环境温度偏低"}]', 'A', '起泡多因界面存在污染物或挥发性物质受热膨胀造成。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '检测涂层漏点（针孔、漏涂）最常用的方法是？', '[{"key": "A", "text": "电火花检漏（湿海绵法或高压电火花法）"}, {"key": "B", "text": "目视观察"}, {"key": "C", "text": "敲击听音"}, {"key": "D", "text": "称重计量"}]', 'A', '非导电涂层用湿海绵法，厚涂层用高压电火花法检测漏点。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '涂层附着力检测常用方法有？', '[{"key": "A", "text": "拉拔法与划格（划圈）法"}, {"key": "B", "text": "测厚仪测量"}, {"key": "C", "text": "电火花检漏"}, {"key": "D", "text": "硬度计测定"}]', 'A', '附着力通过拉拔或划格法评定，测厚仪测厚度、电火花查漏点。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '涂层出现“橘皮”的主要原因通常是？', '[{"key": "A", "text": "雾化不良、溶剂挥发过快或涂料粘度过高"}, {"key": "B", "text": "涂层厚度不足"}, {"key": "C", "text": "基材过于清洁"}, {"key": "D", "text": "环境湿度过大"}]', 'A', '橘皮与雾化状态、溶剂挥发速率及粘度密切相关。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '涂层“龟裂（开裂）”常见的原因是？', '[{"key": "A", "text": "涂层过厚、层间配套不当或固化应力过大"}, {"key": "B", "text": "涂层偏薄"}, {"key": "C", "text": "粗糙度偏高"}, {"key": "D", "text": "环境温度偏低"}]', 'A', '过厚与配套不当会造成内应力集中，导致开裂。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '发现干膜厚度低于设计要求的正确处理是？', '[{"key": "A", "text": "打磨清洁后按工艺补涂至合格厚度"}, {"key": "B", "text": "直接加涂一道面漆即可"}, {"key": "C", "text": "忽略不计"}, {"key": "D", "text": "加大量稀释剂重喷薄涂"}]', 'A', '厚度不足必须补涂到位，过度稀释只会加剧质量风险。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '返修前对缺陷部位的处理通常包括？', '[{"key": "A", "text": "铲除或打磨至完好涂层边缘，清洁并做过渡打磨"}, {"key": "B", "text": "直接在缺陷上覆盖补涂"}, {"key": "C", "text": "用腻子填补平整"}, {"key": "D", "text": "喷水冲洗后补涂"}]', 'A', '返修必须去除失效涂层并形成过渡区，才能保证搭接处结合良好。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '涂层“漏涂（漏铁）”在哪个阶段发现最经济？', '[{"key": "A", "text": "施工过程中的逐道过程检验"}, {"key": "B", "text": "竣工验收阶段"}, {"key": "C", "text": "投用运行之后"}, {"key": "D", "text": "大修期间"}]', 'A', '过程检验能及时发现并修补，避免后期铲除返工造成更大损失。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '下列属于常见涂层缺陷的有？', '[{"key": "A", "text": "流挂、橘皮"}, {"key": "B", "text": "针孔、漏涂"}, {"key": "C", "text": "起泡、龟裂"}, {"key": "D", "text": "附着力良好、厚度均匀"}]', 'A,B,C', '附着力良好、厚度均匀属合格表现，不属于缺陷。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '涂层质量的检测手段包括？', '[{"key": "A", "text": "目视与放大镜检查"}, {"key": "B", "text": "干膜测厚仪"}, {"key": "C", "text": "电火花检漏仪"}, {"key": "D", "text": "拉拔式附着力测试仪"}]', 'A,B,C,D', '四项分别用于外观、厚度、漏点与附着力检验。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '涂层起泡的可能原因有？', '[{"key": "A", "text": "基材表面残留油污、水分或盐分"}, {"key": "B", "text": "涂层间溶剂未充分挥发"}, {"key": "C", "text": "施工环境湿度大、表面结露"}, {"key": "D", "text": "涂料搅拌方式不当混入气泡"}]', 'A,B,C,D', '四项均会导致起泡。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '涂层返修的标准流程包括？', '[{"key": "A", "text": "界定缺陷范围并做标记"}, {"key": "B", "text": "铲除或打磨至完好涂层边缘"}, {"key": "C", "text": "清洁表面并做过渡打磨"}, {"key": "D", "text": "按原工艺分层补涂并复检"}]', 'A,B,C,D', '返修须形成完整闭环，最后必须复检确认合格。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '影响涂层附着力的因素有？', '[{"key": "A", "text": "表面处理等级与锚纹深度"}, {"key": "B", "text": "表面清洁度（油、水、盐分）"}, {"key": "C", "text": "涂装间隔时间与层间配套性"}, {"key": "D", "text": "涂料包装桶的品牌"}]', 'A,B,C', '包装品牌与附着力无因果关系。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '针孔会形成腐蚀介质通道，必须检出并修补。', '', '对', '针孔是点蚀与涂层失效的起始点。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '涂层越厚越好，不会产生任何缺陷。', '', '错', '过厚会造成内应力增大、开裂与附着力下降。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '电火花检漏可用于检测涂层漏点。', '', '对', '这是防腐涂层漏点检测的常规手段。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '涂层起泡只与涂料质量有关，与表面处理无关。', '', '错', '表面残留油污水盐是起泡的主要原因之一。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '涂层附着力可采用拉拔法检测。', '', '对', '拉拔法可量化附着力等级，是常用检测方法。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '返修时可直接在缺陷涂层上覆盖补涂，无需处理。', '', '错', '必须去除失效涂层并做过渡处理，否则返修无效。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '涂层龟裂常与涂层过厚或层间配套不当有关。', '', '对', '内应力与配套性是龟裂的主要成因。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '涂装间隔时间过长且未做拉毛处理，可能影响层间附着力。', '', '对', '超时涂层表面已完全固化，需拉毛以恢复机械咬合。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '干膜厚度是评价涂层质量的重要指标之一。', '', '对', '厚度直接决定防腐寿命，是必检项目。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '漏涂在竣工验收时发现比在施工过程中发现成本更低。', '', '错', '越晚发现返工成本越高，过程检验最经济。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '列举常见涂层缺陷及其主要成因。', '', '①流挂：单道过厚、稀释过度、喷距过近；②橘皮：雾化不良、溶剂挥发过快、粘度过高；③针孔：涂料中气泡、基材有杂质、涂层过薄或未完全润湿；④起泡：基材残留油污水盐、层间溶剂残留；⑤龟裂：涂层过厚、层间配套不当、应力集中；⑥漏涂：走枪路线遗漏、边角与焊缝难覆盖；⑦附着力不良：表面处理不达标、间隔超时未拉毛。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '涂层针孔有哪些危害？如何检测与处理？', '', '危害：针孔形成直接通向基材的通道，腐蚀介质沿针孔渗入引起点蚀，是涂层早期失效的主要起点，同时显著降低绝缘性能、影响阴极保护效果。检测：非导电薄膜用湿海绵（低压）法，较厚涂层用高压电火花检漏法，配合目视检查。处理：标记漏点位置，打磨清洁后按原工艺补涂，并重新检漏确认合格。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述涂层返修的标准工艺流程。', '', '①确认并界定缺陷范围，标记边界与部位；②铲除或用砂轮机、动力工具打磨去除失效涂层至完好涂层边缘；③对边缘做 45° 左右过渡打磨（羽化），形成平滑搭接区；④清洁表面去除粉尘与油污，必要时重新除锈至规定等级；⑤按原涂层体系分层补涂，控制各道膜厚与间隔时间；⑥固化后复检厚度、外观、漏点与附着力，记录归档。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '影响涂层附着力的主要因素有哪些？如何检测？', '', '因素：①表面处理等级与锚纹深度是否达标；②表面清洁度（油、水、盐分、粉尘）；③涂装间隔时间及是否做拉毛处理；④底漆与面漆的层间配套性；⑤固化温度与时间；⑥涂料配比是否正确。检测：拉拔法（测定附着强度与破坏界面）与划格/划圈法（评定等级），必要时结合层间剥离试验判断失效界面位置。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '如何通过过程控制减少涂层缺陷？', '', '①严格执行表面处理标准并检验除锈等级、粗糙度与清洁度；②控制环境条件（相对湿度、露点、温度）并做好记录；③按说明书控制配比、稀释与适用期；④执行工艺卡规定的道数、膜厚、间隔时间；⑤每道工序进行目视与厚度过程检验，边角与焊缝加强检查；⑥发现缺陷立即返修并追溯原因；⑦建立工序交接与留痕机制，明确责任。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '储罐底板涂层电火花检漏发现大量漏点，请分析原因并提出处理方案。', '', '原因分析：①涂层偏薄，单道喷涂过厚或道数不足；②基材表面残留油污水盐导致局部回缩、润湿不良；③涂料施工时混入气泡（搅拌过度、稀释过量）；④焊缝及边角部位漏涂或涂装不完整；⑤固化条件不足。处理方案：逐点标记漏点位置，打磨清洁后按工艺补涂，边角与焊缝单独加强；补涂后重新检漏直至合格；同时复核施工记录，追查表面处理与膜厚控制环节，制定纠正与预防措施。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某管道涂层局部剥离，破坏界面位于底漆与基材之间。请分析可能原因。', '', '界面位于底漆与基材之间，说明基材与底漆的结合失效，可能原因：①表面处理等级不足（未达 Sa2.5）或有氧化皮残留；②表面存在油污、水分、盐分污染；③喷砂后间隔时间过长已返锈；④压缩空气含油含水污染基材；⑤环境湿度高、表面结露即涂装。处理：铲除剥离区域，重新除锈至规定等级并检测清洁度，控制温湿度与涂装间隔，按原体系重新涂装并做附着力验证。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '冬季施工后涂层出现网状龟裂，请分析原因与处理办法。', '', '原因：①单道涂层过厚，表干快于内部固化，产生收缩应力；②低温导致固化不完全、涂膜脆性增大；③层间配套不当（如硬面层软底层的组合）；④施工环境温度低于产品允许下限。处理办法：铲除龟裂涂层至完好部位，打磨过渡后重涂；调整施工方案（选用低温型涂料、搭设保温棚、提高环境温度）、控制单道膜厚并在厂家推荐温度范围内施工；复检附着力与外观合格后方可交付。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '返修完成后补涂区域的涂层颜色与厚度与原涂层存在差异，验收时可能被质疑。请给出处理思路。', '', '处理思路：①厚度差异应通过补涂至设计厚度并逐点测厚，确保满足要求，这是验收的硬指标；②颜色差异属外观问题，应对齐涂料批号与厂家，必要时整段或整面重新涂装面漆以消除色差；③保留返修记录、测厚数据与材料证明，向监理与业主说明返修过程与检验结果；④对色差明显的可视部位，事先与业主约定验收口径，避免验收争议。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某项目临近交付时发现大面积针孔，工期不足三天。请组织返修方案。', '', '组织方案：①立即停止无关作业，集中人力并划分区域，按检漏结果标记全部针孔点位；②对每个点位打磨、清洁并分层补涂，重点检查焊缝与边角；③启用增温除湿设备改善固化条件，缩短层间间隔；④增派质检人员分片包干，边补涂边检漏、边复检，形成闭环；⑤对补涂区域做厚度与附着力抽检；⑥制定赶工安全措施（夜间照明、通风、用电安全）并做好记录；⑦如确实无法按期全部完成，应提前向项目经理与业主报告，争取分段验收或顺延，切忌隐瞒缺陷交付。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '3PE 防腐层自内向外（自钢管表面向外）的三层依次是？', '[{"key": "A", "text": "环氧粉末、共聚物胶粘剂、聚乙烯"}, {"key": "B", "text": "聚乙烯、胶粘剂、环氧粉末"}, {"key": "C", "text": "环氧煤沥青、玻璃布、聚乙烯"}, {"key": "D", "text": "富锌底漆、云铁中间漆、面漆"}]', 'A', '3PE 的典型结构为底层环氧粉末、中间胶粘剂、外层聚乙烯。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '3PE 中主要提供附着力与抗阴极剥离能力的层是？', '[{"key": "A", "text": "环氧粉末底层"}, {"key": "B", "text": "胶粘剂中间层"}, {"key": "C", "text": "聚乙烯面层"}, {"key": "D", "text": "外保护层"}]', 'A', '底层环氧与钢面直接结合，是抗阴极剥离性能的主要贡献者。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '3PE 中聚乙烯面层的主要作用是？', '[{"key": "A", "text": "提供机械保护与阻水防渗"}, {"key": "B", "text": "提供附着力"}, {"key": "C", "text": "提供抗阴极剥离"}, {"key": "D", "text": "提高导电性能"}]', 'A', 'PE 层强度高、吸水率低，主要起机械保护与阻隔作用。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '3PE 涂敷前钢管表面处理通常要求达到？', '[{"key": "A", "text": "Sa2.5 级并控制规定锚纹深度"}, {"key": "B", "text": "St2 手工除锈"}, {"key": "C", "text": "无需处理"}, {"key": "D", "text": "仅做除油处理"}]', 'A', '表面处理质量直接决定 3PE 剥离强度与使用寿命。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '3PE 管道设置“管端预留（留端）”的目的是？', '[{"key": "A", "text": "便于现场焊接，避免焊接高温破坏涂层"}, {"key": "B", "text": "节约涂料成本"}, {"key": "C", "text": "便于运输吊装"}, {"key": "D", "text": "便于打印标识"}]', 'A', '焊接热影响会使涂层烧损，故需预留裸管段并做焊接保护。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '3PE 常见的涂敷施工方式包括？', '[{"key": "A", "text": "挤出包覆与缠绕（纵向/横向）"}, {"key": "B", "text": "刷涂与滚涂"}, {"key": "C", "text": "静电粉末喷涂单层"}, {"key": "D", "text": "热浸镀锌"}]', 'A', '3PE 工业化涂敷以挤出包覆或缠绕方式为主。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '评价 3PE 层间结合可靠性的关键指标是？', '[{"key": "A", "text": "层间剥离强度"}, {"key": "B", "text": "涂层颜色"}, {"key": "C", "text": "钢管长度"}, {"key": "D", "text": "环境温度"}]', 'A', '层间剥离强度不足会造成层间分离、进水失效。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '阴极剥离试验主要评价涂层在什么条件下的抵抗能力？', '[{"key": "A", "text": "阴极保护（电解）环境下的抗剥离能力"}, {"key": "B", "text": "高温环境下的硬度"}, {"key": "C", "text": "紫外线下的色牢度"}, {"key": "D", "text": "低温下的柔韧性"}]', 'A', '阴极剥离是埋地管道防腐层的关键性能指标。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '3PE 管道现场焊缝补口通常采用的材料是？', '[{"key": "A", "text": "热收缩带（套）"}, {"key": "B", "text": "普通透明胶带"}, {"key": "C", "text": "水泥砂浆"}, {"key": "D", "text": "普通调和漆"}]', 'A', '热收缩带（套）是 3PE 管道补口的标准做法。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '涂敷加热温度控制不当最可能导致的后果是？', '[{"key": "A", "text": "胶粘剂失效、层间剥离强度不足"}, {"key": "B", "text": "涂层颜色变浅"}, {"key": "C", "text": "涂层自动变薄"}, {"key": "D", "text": "钢管变形"}]', 'A', '温度过高会使胶粘剂降解，过低则浸润不良，都会降低剥离强度。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '3PE 防腐层的组成部分包括？', '[{"key": "A", "text": "环氧粉末底层"}, {"key": "B", "text": "共聚物胶粘剂中间层"}, {"key": "C", "text": "聚乙烯面层"}, {"key": "D", "text": "玻璃纤维增强布层"}]', 'A,B,C', '3PE 不含玻璃布层，玻璃布常与环氧煤沥青体系配合使用。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '3PE 质量控制的主要检验项目有？', '[{"key": "A", "text": "外观检查"}, {"key": "B", "text": "涂层厚度测量"}, {"key": "C", "text": "层间剥离强度试验"}, {"key": "D", "text": "电火花检漏"}]', 'A,B,C,D', '四项均为 3PE 质量的常规检验项目。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '影响 3PE 层间剥离强度的因素有？', '[{"key": "A", "text": "钢管表面处理质量与锚纹深度"}, {"key": "B", "text": "涂敷加热温度与时间控制"}, {"key": "C", "text": "胶粘剂的性能与挤出量"}, {"key": "D", "text": "钢管的出厂长度"}]', 'A,B,C', '钢管长度与剥离强度无因果关系。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '关于管端预留，正确的做法有？', '[{"key": "A", "text": "按规范要求控制预留长度"}, {"key": "B", "text": "预留部位做可焊性临时防护"}, {"key": "C", "text": "预留长度越大越好"}, {"key": "D", "text": "焊接前清除预留区锈蚀与污染"}]', 'A,B,D', '预留长度过大会增大补口工作量并增加裸露风险，应按规定值控制。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '3PE 常见的质量问题有？', '[{"key": "A", "text": "层间剥离强度不足"}, {"key": "B", "text": "涂层厚度不均"}, {"key": "C", "text": "存在漏点（针孔）"}, {"key": "D", "text": "管端涂层故意加厚以便焊接"}]', 'A,B,C', '管端需预留裸管，不存在“加厚便于焊接”的做法。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '3PE 由环氧粉末、胶粘剂和聚乙烯三层构成。', '', '对', '这是 3PE 的标准三层结构。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '聚乙烯面层主要提供附着力与抗阴极剥离性能。', '', '错', '这两项主要由底层环氧粉末负责，PE 层主要提供机械保护与阻水。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '管端预留的目的是便于现场焊接，避免高温破坏涂层。', '', '对', '焊接热输入会烧损涂层，故须预留裸管。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '3PE 涂敷前钢管表面处理应达到 Sa2.5 级。', '', '对', '表面处理不达标会直接导致剥离强度不足。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '层间剥离强度是评价 3PE 质量的关键指标。', '', '对', '它反映层间结合的可靠性。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '3PE 管道现场补口通常采用热收缩带（套）。', '', '对', '热收缩带是标准补口材料。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '涂敷温度过高或过低都会影响层间剥离强度。', '', '对', '温度偏离工艺窗口会降低结合质量。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '3PE 涂层只需进行外观检查即可判定合格。', '', '错', '还需检验厚度、剥离强度与漏点等指标。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '阴极剥离性能是评价防腐层的重要指标。', '', '对', '尤其对采用阴极保护的埋地管道更为关键。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '管端预留长度越大越好。', '', '错', '应按规范控制预留长度，过大反而增加补口工作量与风险。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述 3PE 防腐层的结构及各层的主要作用。', '', '结构自钢管表面向外为：①环氧粉末底层（FBE）：与钢面牢固结合，提供附着力和抗阴极剥离性能，是防腐的关键层；②共聚物胶粘剂中间层：在环氧层与聚乙烯层之间形成牢固粘结，起桥接作用；③聚乙烯面层：提供机械保护、阻水防渗与抗土壤应力作用。三层共同构成机械强度高、绝缘性能好、耐久的管道外防腐体系。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '3PE 涂敷的主要工艺流程与关键控制参数有哪些？', '', '流程：钢管检验与预热 → 表面处理（抛丸/喷砂至 Sa2.5）→ 除尘与加热 → 静电喷涂环氧粉末 → 挤出胶粘剂与聚乙烯（或缠绕）→ 冷却定型 → 管端处理 → 检验（外观、厚度、剥离强度、电火花检漏）→ 标识与堆放。关键控制参数：表面处理等级与锚纹、钢管预热温度、环氧喷涂温度与膜厚、胶粘剂挤出温度与量、PE 层厚度与冷却速率。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '为什么要做管端预留？施工中应注意哪些问题？', '', '原因：现场环焊缝焊接时热输入极大，会烧损涂层，因此需在管端预留一定长度的裸管段。注意事项：①按规范要求控制预留长度；②预留部位在运输和堆放期间应采取临时防护（如可焊性底漆或专用保护套），防止锈蚀与机械损伤；③焊接前应清除预留区的锈蚀、油污与飞溅物；④焊接完成后及时进行补口作业，避免裸管长期暴露。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '3PE 防腐管的主要质量检验项目及判定依据是什么？', '', '主要项目：①外观：涂层连续、无气泡、无破损、无皱褶；②厚度：按管径等级对应设计要求，逐根抽测；③层间剥离强度：按标准方法在（通常）规定温度下测试，应不低于标准规定值；④电火花检漏：按涂层厚度选择检漏电压，不允许有漏点；⑤阴极剥离：按标准在规定的试验周期与温度下评定剥离半径。判定依据为相应的国家或行业标准及设计文件要求。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '3PE 常见质量问题及原因分析。', '', '①层间剥离强度不足：表面处理不达标、温度控制不当、胶粘剂用量或性能不足；②涂层厚度不均：挤出/缠绕工艺参数波动、钢管椭圆度大；③漏点与针孔：粉末受潮、喷涂参数不当、机械损伤；④层间分离或翘边：冷却不充分、存放温度过高或吊装磕碰；⑤管端涂层烧损：焊接未做保护。应针对具体原因从材料、工艺与操作三方面整改。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某批 3PE 防腐管层间剥离强度检验不合格，请分析原因并给出整改方向。', '', '原因分析：①表面处理未达 Sa2.5 或锚纹深度不足，环氧层与钢面结合不良；②钢管预热温度偏低，粉末熔融流平不充分或胶粘剂浸润不良；③加热温度过高使胶粘剂或环氧层降解；④胶粘剂挤出量与厚度控制不当；⑤冷却速率不当造成内应力。整改方向：复核并校准抛丸与加热工序参数，逐根检测表面处理等级与锚纹；按工艺窗口控制预热与挤出温度并做好温度记录；抽检原材料（环氧粉末、胶粘剂、PE）性能；对不合格管段铲除涂层后重新涂敷，并加强过程检验。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '3PE 管道现场焊缝补口完成后不久出现翘边、进水。请分析原因与处理措施。', '', '原因：①补口前预留区表面处理不洁净或有锈蚀、水分；②热收缩带加热不均匀、收缩不到位，搭接量不足；③底漆（如环氧补口漆）涂刷不均匀或未固化即施工；④施工环境湿度大、温度低，影响粘结；⑤回填时机械损伤。处理措施：拆除失效补口材料，清理表面至合格并烘干；按规定涂刷配套底漆并控制固化；采用合格热收缩带，保证搭接量与均匀加热收缩；环境不满足时暂停施工；回填时采取保护措施（砂垫层、警示带）。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '3PE 管在运输与施工现场堆放过程中出现涂层机械损伤，请说明防护与修补办法。', '', '防护：①运输与装卸使用专用吊具（尼龙吊带），严禁钢丝绳直接勒紧与拖拽；②管间加软质垫木或橡胶垫，分层堆放并设挡枕防止滚动；③现场堆放场地平整、无尖锐杂物，避免长时间暴晒。修补：①对轻微划伤、擦伤，按厂家提供的修补材料（如补伤片、热熔修补棒）进行修补；②对破损面积较大的部位，切除失效涂层边缘并做过渡打磨，采用热收缩补伤片或喷涂修补；③修补后进行电火花检漏与外观检验，确保无漏点后回填。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '现场对 3PE 防腐管进行冷弯或弯管加工后，涂层出现开裂。请分析并提出解决思路。', '', '原因：①3PE 涂层刚性较大，聚乙烯层与环氧层的延伸率不同，冷弯时弯曲应力超过涂层承受能力；②弯曲半径过小；③环境温度过低使涂层脆性增大。解决思路：①尽量采用工厂预制的弯管，在涂敷前完成弯制；②现场弯管时控制弯曲半径不小于规范要求，并在允许温度下作业；③对必须现场弯制的管段，弯后全面检查并修补损伤部位，必要时采用柔性补口材料；④弯制过程做好涂层保护（软质垫层）。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '阴极保护系统检测发现某段 3PE 管道绝缘性能明显下降，请给出排查思路。', '', '排查思路：①先确认测试方法正确（密间隔电位、电流衰减等），排除检测误差；②检查补口与弯头、三通等异形部位涂层完整性，这些部位是薄弱点；③用地面电火花或交流电位梯度法（PCM/ACVG）定位涂层破损点；④开挖验证并检查是否存在机械损伤、土壤应力开裂或阴极剥离；⑤检查是否存在金属搭接（如未绝缘的支架、套管）造成短路；⑥确认阴极保护参数（保护电位、电流）是否正常；⑦根据结果修补涂层破损点、消除搭接并复测绝缘性能。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '环氧粉末（FBE）涂层的成膜方式是？', '[{"key": "A", "text": "静电喷涂后经加热熔融流平并交联固化"}, {"key": "B", "text": "常温自然干燥成膜"}, {"key": "C", "text": "刷涂后晾干"}, {"key": "D", "text": "热浸镀成膜"}]', 'A', 'FBE 属熔结型粉末涂层，必须依靠热量熔融固化。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, 'FBE 喷涂通常采用下列哪种工艺？', '[{"key": "A", "text": "静电喷涂（粉末带电吸附于接地钢管）"}, {"key": "B", "text": "火焰喷涂"}, {"key": "C", "text": "高压无气喷涂"}, {"key": "D", "text": "空气喷涂"}]', 'A', '静电喷涂可使粉末均匀吸附在接地钢管表面。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, 'FBE 施工中控制固化温度窗口的主要意义是？', '[{"key": "A", "text": "既保证充分固化和流平，又避免过烘烤导致涂层降解"}, {"key": "B", "text": "仅影响涂层颜色"}, {"key": "C", "text": "仅影响涂层厚度"}, {"key": "D", "text": "对质量没有实质影响"}]', 'A', '温度偏低固化不足，偏高则涂层脆化、性能下降。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '单层 FBE 防腐层的常见厚度范围是？', '[{"key": "A", "text": "约 300～500 μm"}, {"key": "B", "text": "约 50 μm"}, {"key": "C", "text": "约 2 mm"}, {"key": "D", "text": "约 10 mm"}]', 'A', '单层 FBE 厚度通常在数百微米量级，具体按标准与管径确定。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, 'FBE 涂敷对表面处理的要求是？', '[{"key": "A", "text": "达到 Sa2.5 级并控制锚纹深度与清洁度"}, {"key": "B", "text": "仅需除油"}, {"key": "C", "text": "无需处理"}, {"key": "D", "text": "达到 St2 即可"}]', 'A', 'FBE 依靠机械咬合与化学键结合，表面处理极为关键。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, 'FBE 涂层出现“针孔”的危害是？', '[{"key": "A", "text": "形成腐蚀通道，须用电火花检漏检出并修补"}, {"key": "B", "text": "仅为外观问题"}, {"key": "C", "text": "可增加涂层附着力"}, {"key": "D", "text": "可提高绝缘电阻"}]', 'A', '针孔是 FBE 涂层失效的主要诱因之一。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '胶化时间（gel time）指标主要反映环氧粉末的？', '[{"key": "A", "text": "固化反应速度，影响施工窗口与固化质量"}, {"key": "B", "text": "涂层颜色深浅"}, {"key": "C", "text": "涂层厚度"}, {"key": "D", "text": "粉末的流动粘度"}]', 'A', '胶化时间过短会流平不良，过长则固化不足。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '钢管预热温度过高会使 FBE 涂层？', '[{"key": "A", "text": "过早胶化、流平不良，易产生气泡与漏点"}, {"key": "B", "text": "表面更加平整"}, {"key": "C", "text": "厚度自动增加"}, {"key": "D", "text": "耐候性显著提高"}]', 'A', '预热温度过高会缩短流平时间窗口，形成缺陷。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, 'FBE 与 3PE 的主要区别是？', '[{"key": "A", "text": "FBE 为单层环氧粉末涂层，3PE 在其上再加胶粘剂与聚乙烯层"}, {"key": "B", "text": "两者结构完全相同"}, {"key": "C", "text": "FBE 属于保温层"}, {"key": "D", "text": "3PE 中不含环氧粉末"}]', 'A', '3PE 的底层即为 FBE，两者是包含关系而非等同关系。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, 'FBE 涂层出厂检验的常规项目包括？', '[{"key": "A", "text": "厚度、电火花检漏、附着力（及阴极剥离）"}, {"key": "B", "text": "仅外观检查"}, {"key": "C", "text": "仅颜色比对"}, {"key": "D", "text": "仅称重计量"}]', 'A', 'FBE 需通过多项性能检验才能判定合格。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, 'FBE 涂敷质量控制项目包括？', '[{"key": "A", "text": "涂层厚度"}, {"key": "B", "text": "电火花检漏"}, {"key": "C", "text": "附着力与阴极剥离性能"}, {"key": "D", "text": "原材料胶化时间与含水率"}]', 'A,B,C,D', '原材料性能与成品性能共同决定质量，均需控制。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '影响 FBE 涂层质量的主要因素有？', '[{"key": "A", "text": "表面处理质量与锚纹深度"}, {"key": "B", "text": "钢管预热温度与固化温度"}, {"key": "C", "text": "粉末性能与喷涂参数"}, {"key": "D", "text": "钢管的出厂长度"}]', 'A,B,C', '钢管长度与涂层质量无直接关系。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, 'FBE 涂层的常见缺陷有？', '[{"key": "A", "text": "针孔（漏点）"}, {"key": "B", "text": "厚度不足或不均"}, {"key": "C", "text": "未熔颗粒、结块与橘皮"}, {"key": "D", "text": "附着力不良"}]', 'A,B,C,D', '四项均为 FBE 常见缺陷。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, 'FBE 涂敷的表面处理要求包括？', '[{"key": "A", "text": "除锈等级达到 Sa2.5"}, {"key": "B", "text": "锚纹深度控制在规定范围"}, {"key": "C", "text": "表面清洁、无油污与盐分"}, {"key": "D", "text": "表面越光滑越好"}]', 'A,B,C', '过度光滑会降低机械咬合，锚纹需在规定范围内。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '关于 FBE 的应用，下列说法正确的有？', '[{"key": "A", "text": "常用于埋地管道外防腐"}, {"key": "B", "text": "可作为 3PE 防腐层的底层"}, {"key": "C", "text": "可用于管道内壁防腐"}, {"key": "D", "text": "仅适用于混凝土结构"}]', 'A,B,C', 'FBE 适用于金属管道，混凝土地坪等不属其典型应用。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, 'FBE 通过静电喷涂并加热熔融固化形成涂层。', '', '对', '这是 FBE 的基本成膜机理。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, 'FBE 可以像普通油漆一样常温自干成膜。', '', '错', 'FBE 必须依靠加热熔融交联固化。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '单层 FBE 涂层厚度通常在数百微米量级。', '', '对', '具体厚度按执行标准与管径要求确定。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '预热温度过高会造成粉末过早胶化、流平不良。', '', '对', '流平时间窗口被压缩，易形成缺陷。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '电火花检漏可用于发现 FBE 涂层的漏点。', '', '对', '检漏是 FBE 质量控制的必检项目。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '锚纹深度对 FBE 的附着力没有影响。', '', '错', '锚纹过浅或过深都会影响附着力。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '胶化时间会影响施工窗口和固化质量。', '', '对', '胶化时间是粉末的关键工艺指标。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, 'FBE 可以作为 3PE 防腐层的底层。', '', '对', '3PE 的底层即为熔结环氧粉末。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, 'FBE 涂层不需要做附着力检验。', '', '错', '附着力是 FBE 的关键性能指标，必须检验。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '表面处理不达标会导致 FBE 附着力下降。', '', '对', '表面处理是 FBE 质量的第一要素。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述 FBE 的成膜原理与主要施工流程。', '', '成膜原理：环氧粉末经静电场带电后吸附于已预热且接地的钢管表面，靠钢管余热使粉末熔融、流平，并通过交联反应固化成膜，形成连续致密的防腐层。主要流程：钢管检查 → 表面处理（抛丸至 Sa2.5）→ 除尘 → 中频加热至规定温度 → 静电喷涂环氧粉末 → 熔融流平与固化 → 水冷 → 管端处理 → 检验（厚度、电火花检漏、附着力/阴极剥离）→ 标识堆放。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, 'FBE 施工对表面处理与预热温度有哪些要求？为什么？', '', '表面处理要求：除锈等级达 Sa2.5，锚纹深度控制在规定范围（通常约 40～100 μm），表面无油污、水分、盐分与粉尘。原因：FBE 与钢面结合依靠机械咬合和化学键，锚纹提供咬合面积与结构。预热温度要求：控制在粉末规定的固化窗口内。原因：温度过低粉末熔融流平不充分、固化不足，附着力与致密性差；温度过高则粉末过早胶化、流平不良，易产生气泡与漏点，过烘烤还会使涂层脆化。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, 'FBE 常见质量缺陷及预防措施有哪些？', '', '①针孔/漏点：粉末受潮、表面有杂质、膜厚不足——应控制粉末含水率、加强表面清洁、保证膜厚；②厚度不足或不均：喷涂参数不稳、走枪不当——应固定工艺参数并加装在线测厚；③未熔颗粒与结块：加热不足或粉末结块——应校准加热温度、筛分粉末；④附着力不良：表面处理不达标、固化不足——应严格检验除锈等级与锚纹、控制固化温度时间；⑤橘皮：流平时间不足——应调整预热与胶化时间匹配。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, 'FBE 与 3PE 的技术差异及适用场景是什么？', '', '技术差异：FBE 为单层熔结环氧粉末涂层，优点是附着力强、抗阴极剥离性能好、耐温性较好，缺点是抗机械冲击与抗土壤应力能力相对较弱；3PE 在 FBE 基础上增加胶粘剂与聚乙烯层，机械强度高、抗冲击与阻水性好，缺点是环氧层较薄、对表面处理与工艺控制要求高，且耐温性受 PE 层限制。适用场景：机械损伤风险大、需长期埋地的干线管道多用 3PE；机械损伤风险小、或需耐较高温度的场合、以及管道内壁防腐多用 FBE。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, 'FBE 涂层的检验项目有哪些？检出不合格时如何处理？', '', '检验项目：外观（连续、无气泡、无漏涂）、涂层厚度（逐根测厚、抽测点数按规定）、电火花检漏（按膜厚选电压，不允许漏点）、附着力（拉拔或划格）、阴极剥离（按规定周期与温度试验）。检出不合格的处理：对局部漏点按厂家修补材料与方法修补并复检；对厚度不足部位补涂至合格；对附着力或阴极剥离不合格的管段，一般不得修补使用，须铲除涂层重新涂敷，同时追溯并整改工艺参数，防止批量复现。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某批 FBE 防腐管电火花检漏漏点数量明显偏多，请分析原因与整改措施。', '', '原因分析：①钢管表面残留盐分、油污或粉尘，造成局部不浸润；②粉末受潮结块，喷出后形成未熔颗粒；③膜厚不足，局部涂层过薄；④预热温度偏低导致熔融流平不充分；⑤喷涂参数（电压、供粉量、走枪速度）不稳定。整改措施：加强表面处理后的清洁与除尘并使用清洁度检测；控制粉末储存与筛分，检测含水率；调整预热温度至规定窗口；稳定喷涂参数并加装在线膜厚监测；对检出漏点按厂家方法修补并重新检漏，对密集不合格管段返工重涂。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, 'FBE 涂层表面出现明显未熔颗粒与结块，请分析原因。', '', '原因：①加热温度不足，粉末来不及完全熔融流平；②粉末在储存中受潮结块，或使用前未过筛；③供粉系统有结块积料，间歇性送入大颗粒；④回收粉掺入比例过高且性能下降；⑤胶化时间过短，粉末未流平即固化。处理：校准加热炉温度并测量钢管实际温度；严格控制粉末储存条件（干燥、密封、先进先出），使用前过筛；清理供粉系统；控制回收粉比例或停用回收粉；选用胶化时间匹配的粉末。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某批管材 FBE 附着力试验不合格（破坏发生在涂层与基材之间），请给出排查思路。', '', '排查思路：①复核表面处理：除锈等级是否达 Sa2.5、锚纹深度是否在规定范围、是否存在个别漏喷或锈斑；②检查表面清洁度：油污、盐分、粉尘残留（做水润湿或盐分检测）；③核对预热温度与固化温度曲线，是否存在温度偏低导致固化不足；④核对涂层厚度是否符合要求（过厚会导致内应力大、附着力下降）；⑤检查粉末是否受潮或超过保质期；⑥检查喷砂用压缩空气是否含油水。针对性整改后做小批量试涂并复检合格再恢复生产。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '冬季施工时 FBE 涂层固化不良、表面发粘。请分析原因并给出解决措施。', '', '原因：①车间或环境温度过低，钢管预热后散热快，实际成膜温度低于设计要求；②加热功率不足或加热时间不够；③管壁厚度大、热容量大，未按实际工况调整加热参数；④粉末胶化时间与环境条件不匹配。解决措施：对车间采取保温措施；提高加热功率或延长加热时间并实测钢管表面温度（用测温仪验证）；按管径与壁厚制定加热参数表；选用适合低温施工的粉末体系；建立固化度抽检（如溶剂擦拭、差示扫描量热）机制，确认合格后再批量生产。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '管道内壁 FBE 涂层局部出现脱落，请分析可能原因。', '', '原因分析：①内壁表面处理不到位（内抛丸/内喷砂受空间限制，易形成死角）；②内壁除尘不彻底，粉尘残留影响附着；③内壁加热不均匀，局部温度不足导致固化不良；④内喷涂参数不适配管径（喷涂距离、喷枪行走速度不当）造成厚度不均；⑤介质工况与涂层耐性不匹配（如介质温度超限或存在强溶剂）；⑥运输安装过程中机械损伤（如内窥检查、清管作业刮擦）。处理：内窥检查定位脱落范围，铲除失效涂层、重新内表面处理并喷涂修补；同时优化内壁除锈、除尘与加热工装，加强厚度与电火花检验。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '下列哪项不属于施工方案的编制依据？', '[{"key": "A", "text": "施工图设计文件与合同要求"}, {"key": "B", "text": "国家及行业技术标准规范"}, {"key": "C", "text": "现场踏勘与施工条件调查结果"}, {"key": "D", "text": "作业人员的个人操作习惯"}]', 'D', '方案依据客观文件与条件，不能以个人习惯为依据。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '施工方案中的“施工部署”主要明确的是？', '[{"key": "A", "text": "施工顺序、流水段划分与资源配置"}, {"key": "B", "text": "材料品牌名称"}, {"key": "C", "text": "办公用品采购"}, {"key": "D", "text": "员工餐补标准"}]', 'A', '施工部署解决“先做什么、在哪做、用什么做”的组织问题。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '对于危险性较大的分部分项工程，正确做法是？', '[{"key": "A", "text": "单独编制专项施工方案并按规定完成审批（必要时论证）"}, {"key": "B", "text": "在班前会上口头交代即可"}, {"key": "C", "text": "由作业班组自行决定做法"}, {"key": "D", "text": "无需交底直接施工"}]', 'A', '危大工程必须专项方案 + 审批流程，属强制性管理要求。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '技术交底的核心目的是？', '[{"key": "A", "text": "使作业人员明确工艺要求、质量标准与安全注意事项"}, {"key": "B", "text": "完成签字手续以备检查"}, {"key": "C", "text": "替代施工方案的作用"}, {"key": "D", "text": "记录施工进度"}]', 'A', '交底是方案落地的手段，核心是让人听懂、会做、做对。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '技术交底一般应在什么时间进行？', '[{"key": "A", "text": "每道工序作业前进行，并坚持分级交底"}, {"key": "B", "text": "工程完工后统一补做"}, {"key": "C", "text": "整个工程只做一次"}, {"key": "D", "text": "只对管理人员交底即可"}]', 'A', '交底须前置且分级：技术负责人→班组长→作业人员。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '施工方案中的“质量控制点”应明确哪些要素？', '[{"key": "A", "text": "检验项目、质量标准、检验频次与责任人"}, {"key": "B", "text": "只写标准不写责任人"}, {"key": "C", "text": "仅列材料清单"}, {"key": "D", "text": "仅列工期节点"}]', 'A', '缺任一要素的控制点都无法闭环，尤其是责任人与频次。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '技术交底记录的正确做法是？', '[{"key": "A", "text": "交底人与被交底人签字确认，并及时归档"}, {"key": "B", "text": "口头说明即可"}, {"key": "C", "text": "事后集中补签"}, {"key": "D", "text": "无需留存"}]', 'A', '签字与归档是交底有效性的凭证，也是责任划分依据。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '施工过程中因现场条件变化需调整施工方案时，应？', '[{"key": "A", "text": "履行设计/方案变更审批程序，并重新组织交底"}, {"key": "B", "text": "现场自行调整后继续施工"}, {"key": "C", "text": "无需告知监理单位"}, {"key": "D", "text": "先施工事后补办手续"}]', 'A', '擅自变更属重大管理违规，可能造成质量与安全责任无法界定。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '编制施工进度计划时应重点考虑的因素是？', '[{"key": "A", "text": "工序逻辑关系、关键线路与资源配置"}, {"key": "B", "text": "仅天气情况"}, {"key": "C", "text": "仅人员数量"}, {"key": "D", "text": "仅材料价格"}]', 'A', '工序逻辑与关键线路决定总工期，资源决定能否落地。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '施工方案中的 HSE 措施应至少包含？', '[{"key": "A", "text": "危险源识别、防护措施与应急处置方案"}, {"key": "B", "text": "仅罗列安全标语"}, {"key": "C", "text": "仅指定一名安全员"}, {"key": "D", "text": "仅购买工程保险"}]', 'A', 'HSE 措施须覆盖识别—防护—应急的完整闭环。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '施工方案通常应包含下列哪些内容？', '[{"key": "A", "text": "编制依据与工程概况"}, {"key": "B", "text": "施工部署与进度计划"}, {"key": "C", "text": "施工工艺与质量控制措施"}, {"key": "D", "text": "安全与环保（HSE）措施"}]', 'A,B,C,D', '四项均为施工方案的必备组成部分。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '技术交底的内容应包括？', '[{"key": "A", "text": "工艺流程与操作要点"}, {"key": "B", "text": "质量标准与检验方法"}, {"key": "C", "text": "安全风险与防护措施"}, {"key": "D", "text": "材料采购价格"}]', 'A,B,C', '材料价格属商务信息，不属于技术交底内容。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '下列属于需编制专项方案的危险性较大工程有？', '[{"key": "A", "text": "高处作业"}, {"key": "B", "text": "受限空间作业"}, {"key": "C", "text": "大型脚手架搭设与拆除"}, {"key": "D", "text": "日常工具清点"}]', 'A,B,C', '工具清点属日常管理，不构成危大工程。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '施工方案编制前的准备工作包括？', '[{"key": "A", "text": "熟悉施工图与设计文件"}, {"key": "B", "text": "现场踏勘与施工条件调查"}, {"key": "C", "text": "收集并确认适用标准规范"}, {"key": "D", "text": "先开工再补方案"}]', 'A,B,C', '无方案先施工属违规，不能作为准备工作。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '确保技术交底有效落实的措施有？', '[{"key": "A", "text": "分级交底并签字确认"}, {"key": "B", "text": "交底内容具体、可操作"}, {"key": "C", "text": "现场跟踪检查执行情况"}, {"key": "D", "text": "仅将文件发到班组微信群"}]', 'A,B,C', '仅发文件无法确认是否理解与执行，不构成有效交底。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '技术交底应在每道工序作业前进行并留存签字记录。', '', '对', '工序前交底 + 签字留痕是基本要求。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '施工方案可以不进行现场踏勘，直接照图编制。', '', '错', '现场条件直接影响工艺与安全措施，必须踏勘。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '危险性较大的分部分项工程应编制专项方案并按程序审批，必要时组织专家论证。', '', '对', '这是强制性管理要求。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '交底记录签字归档后，无需再跟踪现场执行情况。', '', '错', '交底效果必须通过现场检查验证。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '施工方案发生变更时应履行审批手续并重新交底。', '', '对', '变更管理是方案有效性的保障。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '质量控制点应明确检验项目、标准、频次与责任人。', '', '对', '四要素齐备才能实现闭环控制。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '施工进度计划只需考虑天气因素即可。', '', '错', '工序逻辑、关键线路与资源才是决定性因素。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, 'HSE 措施应包括危险源识别与应急处置方案。', '', '对', 'HSE 措施须覆盖识别与应急。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '技术交底可以由班组口头进行，无需形成书面记录。', '', '错', '无书面签字记录则无法追溯，属管理缺陷。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '关键线路上的工序延误将直接影响工程总工期。', '', '对', '关键线路无机动时间，延误即导致总工期顺延。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述施工方案的编制依据与主要内容。', '', '编制依据：施工图设计文件与技术要求、施工合同与工期要求、国家及行业技术标准规范、现场踏勘与施工条件调查结果、企业技术力量与装备条件、类似工程经验。主要内容：编制依据与工程概况、施工部署与组织机构、施工进度计划与资源计划、主要施工工艺与技术措施、质量控制措施与质量目标、HSE 与文明施工措施、成品保护与环境保护措施、应急处置预案、附表附图（平面布置、流程图等）。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '技术交底应如何分级实施？实施要点有哪些？', '', '分级实施：①技术负责人（或方案编制人）向项目管理人员、专业工长交底；②工长（班组长）向作业班组交底；③班组长向具体作业人员交底（班前会）。实施要点：交底必须前置（作业前）、内容具体可操作（工艺参数、质量标准、检验方法、安全要点）、图文结合便于理解、逐级签字确认、交底后跟踪检查执行情况；工序变更或人员更换后应重新交底，并留存记录归档。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '危险性较大工程的专项方案编制与审批有哪些要求？', '', '①在施工前由具备相应能力的工程技术人员编制专项方案；②内容应包括工程概况、编制依据、施工计划、施工工艺技术、施工安全保证措施、劳动力计划、计算书及相关图纸；③由施工单位技术负责人审核签字、加盖单位公章，并报监理单位总监理工程师审查签字；④对超过一定规模的危险性较大工程，应组织专家论证并按论证意见修改完善后再实施；⑤实施前进行专项交底，实施中安排专人监督，方案变更须重新履行审批程序。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '施工方案中质量控制点应如何设置？', '', '设置方法：①依据设计文件与标准，识别影响质量的关键工序与关键参数；②对每道关键工序明确检验项目、质量标准（允许偏差）、检验方法、检验频次与责任人；③区分停工待检点（H 点，必须经监理确认后放行）与见证点（W 点）；④设置首件（首段）验收、隐蔽工程验收与工序交接检查点；⑤形成质量控制点清单纳入方案，并在交底中明确告知作业人员，检验结果记录归档。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '施工方案变更管理有哪些要求？', '', '①任何变更须由提出方书面说明变更原因与影响；②经技术负责人、项目技术部门审核，涉及设计内容的须经设计单位确认并办理设计变更手续；③涉及安全与重大质量的变更须报监理（必要时报业主）审批；④变更批准后及时更新方案版本，回收作废版本并重新组织交底；⑤变更实施后进行效果验证并记录归档；严禁口头变更、先施工后补手续。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某工程因未进行技术交底即开始涂装施工，导致涂层体系用错、整体返工。请从管理角度分析原因并提出整改措施。', '', '管理原因：①项目未建立工序前交底制度或制度形同虚设；②技术人员未在作业前下达交底，班组按经验施工；③材料与工序管理脱节，未核对涂层体系；④缺少过程检查与首件验证环节；⑤责任划分不清，无签字留痕。整改措施：建立“交底—确认—施工—检查”闭环制度，明确每道工序交底责任人与签字要求；实行首件（首段）验收合格后再批量施工；加强材料进场与技术文件核对；对相关责任人进行考核并组织专项培训；完善资料归档与追溯机制。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '工期紧张，项目经理要求“边施工边补编施工方案”，作为技术负责人你应如何应对？', '', '应对方式：①坚持方案先行是法定与规范要求，向项目经理说明无方案施工的法律风险（质量与安全事故责任、监理停工指令、验收受阻）；②对确实紧急的工序，可先编制“临时施工技术措施/作业指导书”并在交底后实施，同时同步组织完整方案编制与审批；③对危险性较大工程绝不妥协，必须先方案与专项交底；④将风险以书面形式提交并请项目经理签认，必要时上报公司技术部门；⑤加快方案编制进度、明确完成时间与责任人。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '施工过程中发现设计图纸与现场实际情况不符（如管道标高、支架位置），应如何处理？', '', '处理流程：①立即停止相关部位施工并保护现场，做好影像与记录；②由技术人员核对图纸与实测数据，确认差异内容与影响范围；③书面向监理单位与设计单位提出设计变更/工程洽商申请，附现场照片与实测数据；④待设计单位出具变更文件、经监理（与业主）审批后，更新施工方案并重新交底；⑤按变更后文件施工并做好验收记录。严禁自行按“实际”施工，避免返工与责任风险。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某项高处作业专项方案未包含脚手架验收要求，导致脚手架使用中发生验收争议。请分析并提出完善建议。', '', '问题分析：方案缺项导致验收标准缺失，现场无据可依；脚手架搭设后未经检验即投入使用，存在坍塌坠落风险；监理与施工方对“是否合格”判断不一致引发争议。完善建议：在专项方案中明确脚手架搭设参数、材料规格、搭设与拆除顺序、验收项目（立杆间距、剪刀撑、连墙件、脚手板铺设、防护栏杆、安全网等）与验收责任人；实行搭设完成后联合验收挂牌制度（合格牌方可使用）；规定使用期间的定期检查与恶劣天气后复检要求；将验收记录纳入工程资料。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '技术交底内容过于笼统（仅说“按规范施工”），作业人员操作出现明显偏差。请提出改进措施。', '', '改进措施：①交底内容具体化：明确工序步骤、工艺参数（温度、压力、膜厚、配比、间隔时间）、质量标准与允许偏差、检验方法；②采用图文结合、样板引路与现场演示方式，必要时组织实操培训；③实行分级交底并逐级签字，交底后由被交底人复述确认理解；④设置首件（首段）验收，以实物样板统一操作标准；⑤技术人员在关键工序旁站指导并跟踪检查执行情况；⑥对偏差及时纠正并纳入班组质量考核。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '工艺卡在现场施工中的核心作用是？', '[{"key": "A", "text": "明确各工序的工艺参数与操作要求，指导现场规范施工"}, {"key": "B", "text": "记录人员考勤"}, {"key": "C", "text": "统计材料价格"}, {"key": "D", "text": "记录当日天气"}]', 'A', '工艺卡是把技术要求转化为可执行参数的核心文件。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '工艺卡中的“工艺参数”通常包括？', '[{"key": "A", "text": "温度、压力、膜厚、时间、配比等控制值"}, {"key": "B", "text": "作业人员姓名"}, {"key": "C", "text": "工资标准"}, {"key": "D", "text": "运输车辆信息"}]', 'A', '工艺参数是工艺卡的主体内容。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '关于作业指导书与工艺卡的关系，正确的是？', '[{"key": "A", "text": "作业指导书侧重具体操作步骤与方法的详细说明，工艺卡侧重参数控制要求"}, {"key": "B", "text": "两者内容完全相同"}, {"key": "C", "text": "两者互不相关"}, {"key": "D", "text": "工艺卡比作业指导书更详细"}]', 'A', '二者互补：一个讲“怎么做”，一个讲“做到什么参数”。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '现场施工中需偏离工艺卡规定参数时，正确做法是？', '[{"key": "A", "text": "停止作业并报技术负责人，履行变更审批后执行"}, {"key": "B", "text": "由操作人员自行调整"}, {"key": "C", "text": "隐瞒不报继续施工"}, {"key": "D", "text": "先完成当前作业再上报"}]', 'A', '擅自偏离工艺参数属严重违规，须走变更流程。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '工艺卡的编制依据应是？', '[{"key": "A", "text": "设计文件、技术标准规范与材料厂家说明书"}, {"key": "B", "text": "个人施工经验估计"}, {"key": "C", "text": "其他工程工艺卡原样复印"}, {"key": "D", "text": "口头要求"}]', 'A', '工艺卡必须依据正式技术文件与材料特性编制。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '工艺卡的正确发放方式是？', '[{"key": "A", "text": "发放至相关作业班组，并做好发放与交底记录"}, {"key": "B", "text": "仅保存在项目部资料柜"}, {"key": "C", "text": "仅报监理备案"}, {"key": "D", "text": "无需发放至现场"}]', 'A', '工艺卡要到达作业层才有效，发放需留痕。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '作业指导书中“关键控制点”的内容要求是？', '[{"key": "A", "text": "明确控制要求、检验方法与异常处理措施"}, {"key": "B", "text": "仅写出控制点名称"}, {"key": "C", "text": "仅写出责任人姓名"}, {"key": "D", "text": "无需在文件中体现"}]', 'A', '关键控制点须可执行、可检验、可处置。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '现场发现工艺卡参数与实际工况明显不匹配时，应？', '[{"key": "A", "text": "反馈技术部门核实，经修订审批后重新发放"}, {"key": "B", "text": "由班组自行涂改参数"}, {"key": "C", "text": "放弃执行工艺卡"}, {"key": "D", "text": "仍按原参数继续施工"}]', 'A', '工艺卡修订须履行审批与受控发放程序。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '工艺卡版本管理的基本要求是？', '[{"key": "A", "text": "受控管理，作废版本及时回收，现场只使用有效版本"}, {"key": "B", "text": "不区分版本编号"}, {"key": "C", "text": "可随意复印分发"}, {"key": "D", "text": "过期版本可继续使用"}]', 'A', '版本失控是现场执行不一致的主要原因。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '首件（首段）验证的主要目的是？', '[{"key": "A", "text": "验证工艺参数与作业指导书的可行性，合格后再批量施工"}, {"key": "B", "text": "完成形象进度指标"}, {"key": "C", "text": "应付上级检查"}, {"key": "D", "text": "收集宣传照片"}]', 'A', '首件验证是批量施工前的重要质量闸门。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '工艺卡通常应包含下列哪些内容？', '[{"key": "A", "text": "工序名称与适用范围"}, {"key": "B", "text": "工艺参数与检验要求"}, {"key": "C", "text": "使用设备与材料要求"}, {"key": "D", "text": "责任人签字与版本信息"}]', 'A,B,C,D', '四项共同构成可执行、可追溯的工艺卡。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '作业指导书一般包括？', '[{"key": "A", "text": "操作步骤与方法"}, {"key": "B", "text": "安全注意事项"}, {"key": "C", "text": "常见异常及处理措施"}, {"key": "D", "text": "材料市场价格信息"}]', 'A,B,C', '价格信息不属于作业指导书内容。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '工艺文件的现场管理要求有？', '[{"key": "A", "text": "受控管理与版本标识"}, {"key": "B", "text": "发放与交底记录"}, {"key": "C", "text": "作废版本及时回收"}, {"key": "D", "text": "随意放置在休息区供人翻阅"}]', 'A,B,C', '随意放置易造成版本混乱与丢失。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '首件验证的作用包括？', '[{"key": "A", "text": "验证工艺参数可行性"}, {"key": "B", "text": "提前发现工艺缺陷"}, {"key": "C", "text": "为批量施工提供统一标准"}, {"key": "D", "text": "替代后续全部检验"}]', 'A,B,C', '首件验证不能替代后续的过程检验与成品检验。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '违反工艺卡作业可能造成哪些后果？', '[{"key": "A", "text": "涂层厚度或性能不达标"}, {"key": "B", "text": "返工与成本增加"}, {"key": "C", "text": "质量事故与责任追究"}, {"key": "D", "text": "施工效率持续显著提高"}]', 'A,B,C', '违反工艺通常导致质量风险与成本上升，不会带来稳定的效率提升。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '工艺卡用于明确各工序的工艺参数与操作要求。', '', '对', '这是工艺卡的基本定位。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '现场可以凭经验自行调整工艺卡规定的参数。', '', '错', '调整须经技术部门审批并重新发放。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '工艺卡应受控管理，并及时回收作废版本。', '', '对', '版本受控是执行一致性的前提。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '作业指导书与工艺卡的内容完全相同。', '', '错', '作业指导书偏操作步骤与方法，工艺卡偏参数控制。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '首件（首段）验证合格后才能批量施工。', '', '对', '首件验证是批量施工的前置条件。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '工艺卡只保存在项目部即可，无需发放到作业班组。', '', '错', '不发放到作业层，工艺卡就失去指导作用。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '偏离工艺卡参数时应停止作业并报技术负责人处理。', '', '对', '这是工艺纪律的基本要求。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '工艺卡应依据设计文件与标准编制，而非凭经验估计。', '', '对', '工艺卡必须建立在正式技术依据之上。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '作废的工艺卡版本可以继续在现场使用至用完为止。', '', '错', '作废版本必须立即回收，严禁继续使用。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '工艺卡应结合现场实际工况适时修订并履行审批程序。', '', '对', '工艺卡需动态维护，但修订必须走受控流程。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '简述工艺卡的作用与主要内容。', '', '作用：把设计文件与标准规范的技术要求转化为现场可直接执行的工艺参数与操作规定，统一施工做法、保证质量一致性，并作为过程检验与责任追溯的依据。主要内容：工序名称与适用范围、施工条件（环境温湿度等）、材料要求与配比、工艺参数（温度、压力、膜厚、时间、速度等）、使用设备与工具、操作要点与注意事项、检验项目与判定标准、常见异常处理、版本号与责任人签字。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '工艺卡与作业指导书有何区别与联系？', '', '区别：作业指导书侧重“怎么做”，详细描述操作步骤、方法、注意事项与异常处理，偏操作程序性文件；工艺卡侧重“做到什么参数”，规定可量化的工艺控制值与检验要求，偏参数控制性文件。联系：二者同源于设计文件与标准规范，互为补充；通常先用作业指导书说明操作流程，再以工艺卡明确关键参数，现场配套使用，共同构成受控工艺文件体系。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '工艺文件的现场管理有哪些要求？', '', '①受控管理：统一编号与版本标识，明确编制、审核、批准人；②发放管理：发放至相关班组并登记签收，同步进行交底；③版本控制：修订后及时发放新版并回收作废版本，现场不得出现多个版本；④现场存放：置于指定位置，保持整洁、可随时查阅，防止污损丢失；⑤执行监督：技术人员与质检人员定期检查执行情况，发现偏离及时纠正；⑥归档：执行记录与修订记录归档保存，便于追溯。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '首件（首段）验证的实施步骤与意义是什么？', '', '实施步骤：①选取具有代表性的首件（首段）部位；②按工艺卡与作业指导书组织施工；③完成后按检验项目全面检验（外观、厚度、附着力/漏点等）；④组织技术、质检、监理（必要时业主）共同确认；⑤合格则形成样板并固化参数，不合格则分析原因调整参数后重新验证；⑥形成首件验收记录并向班组交底推广。意义：提前暴露工艺不适配、参数不合理等问题，避免批量返工；统一操作与验收标准，作为后续施工的实物样板。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '现场偏离工艺卡参数时应如何正确处理？', '', '①作业人员发现参数无法执行或需要调整时，立即停止相关作业并保护现场；②向班组长与技术负责人报告偏离原因、部位与影响范围；③技术负责人核实工况条件，判断是否需要修订工艺卡；④如需修订，按变更程序提出申请，经审核批准后重新发放并交底；⑤对已施工部位进行检验评估，必要时返工处理；⑥记录偏离与处理过程并归档，纳入工艺改进与培训内容。严禁擅自调整或隐瞒不报。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '现场作业人员为便于喷涂，自行加大了稀释剂用量，导致涂层厚度不足、流挂严重。请分析管理问题并提出对策。', '', '管理问题：①工艺卡未明确稀释剂加入量上限或未在交底中强调；②稀释剂未实行限量发放，班组可随意取用；③缺少过程巡检与工艺纪律检查；④操作人员质量意识不足，以“好喷”为优先。对策：在工艺卡中明确稀释比例与允许范围；稀释剂按需限量发放并登记；技术人员与质检员加强巡检，发现即纠正并记录；对违反工艺纪律的行为纳入考核；组织专项培训与首件验证，统一操作标准。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '现场同时出现两个版本的工艺卡，不同班组按不同参数施工，导致同批产品性能不一致。请分析原因与整改措施。', '', '原因：工艺卡修订后未回收旧版，发放登记缺失，现场存放混乱，交底时未说明版本变更内容。整改措施：立即停工核对，统一以最新审批版本为准；收回并作废所有旧版，重新登记发放并交底；建立工艺文件台账（编号、版本、发放范围、回收记录）；规定修订后必须“先回收后发放”；对已按旧版施工的部位进行检验评估，必要时返工；明确工艺文件管理责任人。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '公司首次引进一种新型防腐涂料，现场工艺参数尚不成熟。请设计验证与推广流程。', '', '流程设计：①收集厂家技术资料与推荐参数，编制试验方案与试行工艺卡；②在样板段进行小范围试验，按不同参数组合分组试涂；③按规定龄期检验外观、厚度、附着力及其他性能指标；④比对试验结果，确定最优参数组合并形成正式工艺卡；⑤组织技术、质检、监理共同确认首件（首段）验收；⑥对班组开展专项培训与交底，明确关键控制点与常见问题处理；⑦批量施工阶段加强巡检与抽检，收集数据反馈持续优化；⑧将验证结论与修订后的工艺卡归档。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '冬季施工时，按原工艺卡规定的干燥间隔时间施工，涂层出现层间附着力不良。你应如何处理？', '', '处理方式：①立即暂停后续涂装，对已施工部位做附着力抽检确认影响范围；②分析原因：低温条件下溶剂挥发与固化速率下降，原间隔时间不足，涂膜内部未充分固化即被覆盖；③反馈技术部门，编制冬期施工专项措施（如选用低温型涂料、搭设保温棚、提高环境温度、延长层间间隔、增设强制通风），形成修订版工艺卡并履行审批；④重新交底后组织首件验证；⑤对不合格部位返工；⑥将冬期施工参数纳入企业工艺标准，避免重复发生。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某项目未进行首件验证即全面施工，完成后发现涂层体系局部不配套，出现大面积返工。请分析教训与改进措施。', '', '教训：跳过首件验证使工艺缺陷在批量施工后才暴露，返工量大、成本高、工期受损；同时反映出工艺文件与现场实际脱节、交底与验证环节缺失。改进措施：①将首件（首段）验证设为强制工序节点，未通过不得批量施工；②首件验证须由技术、质检与监理共同确认并形成记录；③完善工艺卡中涂层配套性要求与检验方法；④加强材料进场核对，确认不同材料间的配套性；⑤将首件验证纳入项目质量计划与班组考核，明确未执行的责任追究。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '防腐涂层验收中，“电火花检漏”属于哪一类检验？', '[{"key": "A", "text": "涂层完整性（漏点）检验"}, {"key": "B", "text": "涂层厚度检验"}, {"key": "C", "text": "涂层附着力检验"}, {"key": "D", "text": "外观颜色检验"}]', 'A', '电火花检漏专门用于发现涂层中的漏点与针孔。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '涂层干膜厚度的常用检测方法是？', '[{"key": "A", "text": "使用磁性或涡流测厚仪测量"}, {"key": "B", "text": "目视估计"}, {"key": "C", "text": "称重折算"}, {"key": "D", "text": "敲击听音"}]', 'A', '测厚仪是干膜厚度检测的标准器具，需按规定点数抽测。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '绝热（保温）工程中，保温层厚度的验收要求是？', '[{"key": "A", "text": "按规范规定的允许偏差范围进行检验，不允许出现负偏差超限"}, {"key": "B", "text": "无任何偏差要求"}, {"key": "C", "text": "只要外观平整即可"}, {"key": "D", "text": "只需测量一次即可代表整体"}]', 'A', '保温层厚度不足会直接导致热损失超标，必须按允许偏差检验。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '绝热工程进行表面温度验收的主要目的是？', '[{"key": "A", "text": "验证保温效果满足防烫与热损失控制要求"}, {"key": "B", "text": "检查外表颜色是否美观"}, {"key": "C", "text": "确认材料品牌"}, {"key": "D", "text": "核对施工进度"}]', 'A', '表面温度是保温效果最直观的量化指标。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '涂层附着力的验收常用方法是？', '[{"key": "A", "text": "拉拔法或划格（划圈）法"}, {"key": "B", "text": "电火花检漏"}, {"key": "C", "text": "测厚仪测量"}, {"key": "D", "text": "目视检查"}]', 'A', '附着力通过拉拔或划格法评定。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '工程验收时应首先重点核查的资料是？', '[{"key": "A", "text": "材料合格证与复检报告、隐蔽工程记录与施工记录"}, {"key": "B", "text": "施工日志"}, {"key": "C", "text": "会议纪要"}, {"key": "D", "text": "人员考勤表"}]', 'A', '材料证明与隐蔽记录是质量追溯的核心资料。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '隐蔽工程验收的关键要求是？', '[{"key": "A", "text": "在覆盖前完成检验，并留存影像资料与验收记录"}, {"key": "B", "text": "可在覆盖后补做检验"}, {"key": "C", "text": "由班组自查即可通过"}, {"key": "D", "text": "仅需口头确认"}]', 'A', '隐蔽工程一旦覆盖即无法直接检验，必须覆盖前完成。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '金属外护（保护）层的验收要点包括？', '[{"key": "A", "text": "搭接方向顺水、固定牢固、无翘边与破损"}, {"key": "B", "text": "颜色统一即可"}, {"key": "C", "text": "厚度越大越好"}, {"key": "D", "text": "无需固定"}]', 'A', '外护层失效会导致保温层进水，是保温系统失效的主因之一。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '验收中发现不合格项时，正确的处理方式是？', '[{"key": "A", "text": "下发整改通知，限期整改后重新检验并记录闭环"}, {"key": "B", "text": "口头提示即可"}, {"key": "C", "text": "忽略不影响总体"}, {"key": "D", "text": "直接验收通过"}]', 'A', '不合格项必须整改闭环，不得带病交付。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (1, '分项工程验收合格的基本条件是？', '[{"key": "A", "text": "主控项目全部合格，一般项目满足规范允许偏差要求"}, {"key": "B", "text": "外观美观即可"}, {"key": "C", "text": "只要进度满足要求"}, {"key": "D", "text": "只要业主口头同意"}]', 'A', '主控项目具有否决性，必须全部合格。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '防腐涂层工程验收通常包括哪些检验项目？', '[{"key": "A", "text": "外观检查"}, {"key": "B", "text": "干膜厚度测量"}, {"key": "C", "text": "电火花检漏（漏点）"}, {"key": "D", "text": "附着力试验"}]', 'A,B,C,D', '四项构成防腐涂层验收的基本项目体系。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '绝热（保温）工程验收通常包括哪些项目？', '[{"key": "A", "text": "保温层厚度与外观"}, {"key": "B", "text": "表面温度或热损失"}, {"key": "C", "text": "外护层搭接、固定与密封"}, {"key": "D", "text": "材料合格证与复检报告"}]', 'A,B,C,D', '四项均为保温工程验收的常规内容。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '工程验收应查阅的技术资料包括？', '[{"key": "A", "text": "材料合格证与复检报告"}, {"key": "B", "text": "隐蔽工程验收记录"}, {"key": "C", "text": "施工记录与检验批质量验收资料"}, {"key": "D", "text": "员工工资发放表"}]', 'A,B,C', '工资表与工程质量验收无关。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '关于隐蔽工程验收，正确的要求有？', '[{"key": "A", "text": "在覆盖前完成检验"}, {"key": "B", "text": "留存影像资料与验收记录"}, {"key": "C", "text": "由监理（或业主）见证确认"}, {"key": "D", "text": "覆盖后补做检验即可"}]', 'A,B,C', '覆盖后无法直接检验，不允许以“补检”替代。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (2, '不合格项的处理要求有？', '[{"key": "A", "text": "下发整改通知并限期整改"}, {"key": "B", "text": "整改后重新检验"}, {"key": "C", "text": "严重不合格应返工处理"}, {"key": "D", "text": "处理过程与结果记录闭环归档"}]', 'A,B,C,D', '四项共同构成不合格品的完整处置闭环。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '电火花检漏用于检查防腐涂层的漏点。', '', '对', '它是涂层完整性的主要检验手段。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '涂层干膜厚度可用磁性或涡流测厚仪检测。', '', '对', '测厚仪是标准检测器具，需按规定点数抽测。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '隐蔽工程可以在覆盖完成后再进行检验。', '', '错', '隐蔽工程必须在覆盖前检验并留痕。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '分项工程验收要求主控项目全部合格。', '', '对', '主控项目具有否决性。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '保温层厚度的允许偏差应符合规范规定，不得随意放宽。', '', '对', '厚度不足将直接影响保温效果与节能指标。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '表面温度验收可以反映保温效果。', '', '对', '表面温度是保温效果的直观量化指标。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '工程验收只需检查外观，无需查阅技术资料。', '', '错', '资料是质量可追溯性的依据，必须核查。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '不合格项整改后应重新检验并记录闭环。', '', '对', '整改必须验证有效性。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '金属外护层搭接应顺水方向，防止雨水侵入。', '', '对', '顺水搭接可避免雨水沿缝渗入保温层。', 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (3, '材料合格证与复检报告不是验收的必要资料。', '', '错', '材料证明资料是验收的必备文件。', 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '防腐涂层工程的验收项目与检验方法有哪些？', '', '①外观：目视（必要时用放大镜）检查涂层连续、平整，无流挂、橘皮、气泡、剥落、漏涂；②干膜厚度：使用磁性或涡流测厚仪按规定的检验批与点数抽测，取平均值与最小值判定；③漏点：非导电涂层用湿海绵低压法、较厚涂层用高压电火花检漏法，按膜厚选择电压，不允许漏点；④附着力：拉拔法或划格法，按规定频次抽检；⑤资料：材料合格证与复检报告、施工与检验记录、隐蔽工程记录齐全。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '绝热（保温）工程的验收项目与要求有哪些？', '', '①保温层：厚度按规范允许偏差检验（负偏差不得超限）、表面平整密实、无空鼓脱落、同层错缝、上下层压缝；②防潮层：连续、密封、搭接符合要求，破损处已修补；③外护层：搭接方向顺水、搭接量符合规定、固定牢固（自攻螺钉或捆扎带间距符合要求）、无翘边破损、弯头三通等异形部位处理规范；④表面温度（或热损失）：按设计工况测量，满足防烫与节能要求；⑤资料：保温材料合格证与复检报告、隐蔽工程验收记录、检验批资料齐全。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '隐蔽工程验收有哪些要点与资料要求？', '', '要点：①隐蔽前必须完成自检与专检，并通知监理（业主）到场共同验收；②重点检查表面处理等级与清洁度、涂层道数与厚度、保温层厚度与铺装、防潮层密封情况；③对无法事后复检的部位必须留存影像资料（带标识与时间）；④验收合格签署后放行，方可进行覆盖（如回填、外护安装）；⑤未经验收擅自覆盖的应剥离检查并追究责任。资料要求：隐蔽工程验收记录（含检验数据与结论）、影像资料、材料合格证与复检报告、施工记录。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '工程验收资料通常包括哪些内容？其作用是什么？', '', '主要包括：①材料合格证、出厂检验报告与进场复检报告；②施工记录（含天气、环境温湿度、工序参数、施工部位与数量）；③隐蔽工程验收记录与影像资料；④检验批/分项/分部工程质量验收记录；⑤设计变更、工程洽商与技术核定文件；⑥涂层厚度、漏点、附着力、表面温度等检测报告；⑦竣工图。作用：证明工程质量符合设计与标准要求，是竣工验收与移交的依据，也是质量追溯与责任界定的凭证，出现质量问题时可用于分析与追溯工序环节。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (4, '验收发现不合格项时的处理流程是什么？', '', '流程：①检验人员记录不合格内容、部位、数量与检测数据，并向监理与项目技术负责人报告；②下发不合格品整改通知单，明确整改要求、责任人与完成时限；③责任班组按批准的整改方案（如打磨补涂、重新保温、更换外护等）实施整改；④整改完成后由检验人员重新检验，必要时扩大抽检比例；⑤复检合格后闭合记录并归档；⑥严重不合格或反复出现的问题应组织原因分析，制定纠正与预防措施，并纳入班组考核与工艺改进；⑦严禁以“外观修整”掩盖实质性缺陷交付。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '竣工验收时抽测发现涂层厚度局部低于设计值，但外观平整无明显缺陷。作为验收人员应如何判定与处理？', '', '判定：干膜厚度属主控项目，低于设计值即判定不合格，不能以外观合格替代；应按规范确认测点代表性与不合格区域范围，必要时扩大抽测比例。处理：①责令施工单位查明原因（道数不足、走枪不均、稀释过度等）；②对不合格区域打磨清洁后按工艺补涂至合格厚度，边角与焊缝加强处理；③补涂后重新测厚并复检外观与漏点；④若面积过大或涉及关键部位，应制定专项返修方案并经监理审批；⑤形成不合格处置与复检记录，闭合后重新报验。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某保温管道在检修时发现保温层下管道表面严重腐蚀（CUI）。请从验收角度分析原因。', '', '验收角度分析：①保温材料选用不当或未做防潮层，吸水性大，长期含水导致腐蚀；②外护层搭接方向错误、密封不严或破损未及时修补，雨水渗入；③隐蔽工程（保温层与防腐层）验收未认真检查，未留存影像，缺陷未被发现；④管道防腐层施工质量不合格（厚度不足、存在漏点），且验收时未做电火花检漏；⑤表面温度与热损失检测缺失，未能发现保温层受潮（受潮后表面温度异常）。改进：强化防潮层与外护层验收、严格执行防腐层漏点检验、对易发生 CUI 的部位（低温交替、潮湿环境）采取专门的防护与检测措施。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某工程外护金属板搭接方向做成了“逆水搭接”，验收时未发现，投用后雨水渗入导致保温层受潮。请分析并提出整改与验收改进措施。', '', '问题分析：逆水搭接使雨水沿搭接缝灌入，保温层受潮后导热系数大幅上升，热损失增大并引起管道腐蚀；验收环节未把搭接方向列为检查项，检查不细。整改措施：拆除受潮保温层并干燥或更换；重做防潮层；按顺水搭接（搭接量符合规定）重新安装外护板并可靠固定、密封；弯头与三通等异形部位按规范处理。验收改进：在外护层验收中明确“搭接方向、搭接量、固定间距、密封处理”等check项，纳入检验批记录并留存影像；对雨天或潮湿天气施工加强检查。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '某隐蔽工程未留存影像资料，覆盖后业主对涂层质量提出质疑。作为施工方应如何处理？', '', '处理方式：①调取当时的过程记录与检测数据（厚度、检漏记录、材料证明）作为佐证；②如业主仍不认可，可与业主、监理协商确定有代表性的部位进行局部剥离抽检，以实测结果判定；③如抽检合格，恢复覆盖并留存完整影像与记录，同时完善后续隐蔽工程的影像留存要求；④如抽检不合格，按不合格品处理流程返工；⑤事后应建立隐蔽工程影像留存制度：覆盖前由施工方与监理共同拍摄带部位标识与时间的照片，随验收资料归档，避免类似争议。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (5, '工程已基本完成，监理要求提供保温材料的复检报告，但施工单位仅有厂家合格证、无进场复检报告。应如何处置？', '', '处置方式：①立即核对该批保温材料是否属于规范要求进场复检的品种与项目（导热系数、密度、燃烧性能等）；②若属必检项，补办取样送检手续，由具备资质的检测机构进行复检；③在复检结果出具前，相关部位不得验收交付；④若复检不合格，须更换材料并拆除已施工部位重新施工，同时追溯已覆盖隐蔽部位的检查；⑤完善材料进场验收制度：明确需复检的材料清单、取样见证要求与报告归档流程，避免再次出现资料缺失导致的验收受阻。', NULL, 3, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '2PE 防腐管道是在钢管外壁包覆胶粘剂层、聚乙烯层形成的防腐管道。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '3PE 防腐管道是在钢管外壁涂敷环氧粉末层，并包覆胶粘剂层、聚乙烯层形成的防腐管道。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '产品执行标准：GB/T23257-2017 埋地钢质管道聚乙烯防腐层。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '产品型式检验项目按照标准规定的全部检测项进行检测。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '产品出厂检验项目包括涂层外观、防腐层厚度、漏点。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '环氧粉末在钢管表面形成致密的保护层，具有良好的耐化学腐蚀和抗阴极剥离性能。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '胶粘剂作用是将环氧粉末层和聚乙烯层紧密粘接。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '聚乙烯层的主要作用是机械保护与防腐蚀。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '2/3PE 防腐管道适用于温度不超过80℃的介质输送。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '使用坡口设备在钢管两端进行坡口车削加工，加工出用于施工焊接的端面。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '钢管外壁除锈等级达到Sa2.5级，管道外表呈现银白色金属光泽。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '钢管沿着传输线通过中频加热设备，对钢管进行加热，加热温度达到200±10℃，为后续环氧粉末喷涂及聚乙烯防腐层包覆做准备。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '包覆完成后的管道进入喷淋冷却设备，通过循环水对防腐层进行降温。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '冷却降温使其温度降到60℃以下，确保后续工序中包覆层不发生变形。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '管道冷却后进入管端修整工序，对管口处聚乙烯层进行打磨修整，打磨成30°倒角，防止防腐层翘边。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '防腐厂现有2PE、3PE管道防腐生产设备1套。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '可满足无缝管、直缝管、螺旋焊缝管的生产。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '原材料检验包括环氧粉末检验、胶黏剂检验、聚乙烯树脂检验及钢管检验。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '管体表面除锈后锚纹深度达到50～90μm。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '过程检验：环氧粉末喷涂、胶黏剂及聚乙烯挤出的温度控制符合工艺要求。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '防腐管道25kv检漏电压检测要求无漏点。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '聚乙烯层抗弯曲检验指标无开裂。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '露天存放时间不宜超过6个月，否则应采不透明的遮盖物对防腐管道加以保护。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '3PE防腐管道与2PE防腐管道相比具有优异的抗阴极剥离性能、抗水气渗透性。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '产品施工标准：GB50819油气田集输管道施工规范。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '产品型式检验项目按照标准规定的全部检测项进行检测。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '可生产钢管公称直径最大为1020mm。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '根据防腐层厚度可将产品分为普通级和加强级。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '环氧粉末喷涂前应进行管道的中频加热。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '环氧粉末喷涂采用的是高压静电喷涂设备。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '管道应远离热源或者腐蚀性介质。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '公称直径为300≤DN＜400（mm）的管道存储时堆放层数≤6层。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '施工安装主要工具有喷灯等加热设备、焊接设备。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '我公司现有地面管道外防腐产品有2PE、3PE防腐管道。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '我公司现有地面管道外防腐产品有环氧陶瓷、玻璃釉防腐管道。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '3PE防腐管道埋地使用寿命可达30年以上。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '钢管公称直径DN≤100mm的钢管普通级防腐层最小厚度为1.8mm。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '钢管公称直径DN≤100mm的钢管加强级防腐层最小厚度为2.5mm。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '运输过程中应防止管道碰撞和跌落，避免防腐层的机械损伤。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '产品包装可根据客户要求包装或者散装。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '2PE、3PE防腐管道主要特点是什么？', '', '耐腐蚀：耐酸、碱、盐等化学介质腐蚀；抗冲击；使用寿命长；埋地使用寿命30年以上。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述2PE/3PE防腐管道产品的应用领域？', '', '市政给排水、燃气输送等领域金属管道外防腐；石油天然气输送、化工制药、造纸冶金、煤矿等行业金属管道外防腐；电力、通讯、高速公路等电缆保护金属套管的外防腐。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述2PE防腐管道的应用工况？', '', '适用于土壤相对干燥，常年温度较低，pH值呈中性、弱酸、弱碱性的环境。适用的介质温度不超过80℃。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述3PE防腐管道的应用工况？', '', '适用于土壤温暖潮湿，酸性、碱性强，微生物腐蚀严重，深根植物较多，长期浸水等恶劣环境。适用的介质温度不超过80℃。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '完善3PE防腐管道的生产工艺流程图？', '', '坡口加工 → 表面除锈 → 中频加热 → 环氧粉末喷涂 → 包覆胶黏剂层 → 包覆PE层 → 喷淋冷却 → 管端修整 → 成品检验', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述3PE防腐管道各防腐层的作用。', '', '环氧粉末层：与钢管粘结力强，耐化学腐蚀、抗阴极剥离；胶黏剂层：过渡层，与钢管、环氧涂层、聚乙烯层均能良好粘接；聚乙烯层：具有机械保护与防腐的作用。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述2PE/3PE防腐管道的连接方式及补口防腐处理的结构。', '', '管道采用平口焊接方式连接。管道焊接完成后，补口使用环氧底漆+辐射交联聚乙烯热收缩带（套）的结构进行防腐处理。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '2PE、3PE防腐管道产品的外观要求。', '', '表面平滑，无暗泡、无麻点、无皱折、无裂纹，色泽均匀。管道两端防腐层无翘边。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '试列出不同规格PE防腐管道的产能。', '', '\n钢管直径Ø（mm） | 产量（米/天）\n0≤250 | 1000\n250<Ø≤500 | 500\n500<Ø≤800 | 300\n800<Ø≤1020 | 130', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '完善2PE/3PE防腐管道产品规格型号表中防腐层最小厚度与最高使用温度的指标。', '', '\n钢管公称直径DN（mm） | 防腐层最小厚度 普通级（G）mm | 防腐层最小厚度 加强级（S）mm | 最高使用温度 ℃\nDN≤100 | 1.8 | 2.5 | ≤80\n100<DN≤250 | 2.0 | 2.7 | ≤80\n250<DN<500 | 2.2 | 2.9 | ≤80\n500≤DN<800 | 2.5 | 3.2 | ≤80\n800≤DN≤1020 | 3.0 | 3.7 | ≤80', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '碳锆涂层防腐油管适用于井温不超过95℃的介质环境。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '碳锆涂层防腐油管主要适用于抽油机采油井、电潜泵采油井用的油管。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '按照抗磨抗腐油管通用技术条件钛纳米涂层属于抗腐型。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '碳锆涂层防腐油管执行的石油管理局标准名称为Q/SH1020 1942-2018抗磨抗腐油管 通用技术条件。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '内涂层防腐油管包装规范中，油管两端涂抹螺纹脂，安装螺纹保护器，挂合格证。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '钛纳米与碳锆涂层防腐油管执行的新大企业标准名称为Q/SXD029-2019钛纳米环氧粉末和碳锆环氧粉末内涂层钢质油管。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '将添加了耐腐蚀、高硬度的特种防腐材料制成的碳锆环氧粉末涂料涂敷于油管内表面，通过聚合反应形成致密涂层的防腐管道。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '钛纳米涂层防腐油管涂层主要检测指标包括耐冲击性、附着力、耐化学介质腐蚀、涂层硬度、耐磨性5项。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
