  (6, '钛纳米涂层防腐油管采用接箍连接，中间螺纹部分采用内嵌聚乙烯防腐或涂层防腐。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
