  (6, '碳锆涂层防腐油管的涂层厚度可根据客户需求设计，常规厚度范围350~600μm。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
