  (6, '3 1/2 in油管外径88.90mm。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '碳锆涂层防腐油管的主要特点有哪些？', '', '耐腐蚀。耐原油、污水、化学介质的腐蚀。耐偏磨。碳锆涂层属于抗磨型，落砂法检测值2.9 L/μm。抗冲击。6J冲击涂层不脱落。防结垢。有效减缓水垢、蜡质沉积附着。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '钛纳米涂层防腐油管的主要特点有哪些？', '', '耐腐蚀。钛纳米涂层属于抗腐型，耐污水、化学介质的腐蚀。抗冲击。涂层具有柔韧性，6J冲击涂层不开裂、不脱落。防结垢。涂层光滑，有效减缓水垢沉积附着。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述碳锆涂层防腐油管的应用领域。', '', '适用于有杆采油井、电潜泵采油井、地面输送管道。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述钛纳米涂层防腐油管的应用领域。', '', '适用于油田注水井、地面输送管道。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述内涂层防腐油管生产工艺流程。', '', '油管清理 → 喷砂除锈 → 除尘 → 油管预热 → 喷涂 → 固化 → 检验 → 防护包装', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述内涂层防腐油管产品出厂检验项目。', '', '产品出厂检验项目：涂层外观、涂层针孔数、涂层厚度、附着力、螺纹外观、紧密距、通径检验。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述碳锆涂层防腐油管产品涂层主要检验项目。', '', '耐冲击性、附着力、耐化学介质腐蚀、涂层硬度、耐磨性。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述碳锆涂层防腐油管的适用范围及作用。', '', '碳锆涂层防腐油管主要应用于油田抽油机采油井、电潜泵采油井，用于输送油井采出液，能够有效减缓油管偏磨腐蚀。产品长期使用温度一般不超过95℃，压力≤25MPa。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述钛纳米涂层防腐油管的适用范围及作用。', '', '钛纳米涂层防腐油管主要应用于油田注水井，用于输送污水，能够有效减缓油管腐蚀、水垢沉积。产品长期使用温度一般不超过95℃，压力≤25MPa。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述碳锆涂层防腐油管的规格型号。', '', '2 7/8 in油管、3 1/2 in油管', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料是一种特殊的聚脲涂料由A、B双组份喷涂反应后生成的弹性体物质，是一种新兴的安全防护材料。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, 'A组分由异氰酸酯和多元醇反应生成。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, 'B组分由聚醚胺、扩链剂、填料和助剂组成的混合物。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料具备性能优异、施工快捷、安全环保三大特点。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料施工便捷、用途多样，兼具有防腐、防水功能。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料之所以性能优异，非常稳定，是因为结构中含有大量脲键，其结构对称，具有稳定的特性和优异的键能，因此使涂料性能优异。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料年产能可达到1200吨。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '生产完成的涂料按照不同组分，分别盛装至铁皮桶中。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '灌装后，应充氮气置换桶内的空气，并上紧桶盖，确保密封。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '运输过程中，应小心轻放，严禁撞击，以免泄露。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '储存时应放于阴凉通风处，远离热源。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '包装桶上应注明产品名称、规格、生产日期、生产厂商、厂址、产品批号、净重、保质期、使用说明及注意事项、存储要求等信息，并附带产品质量证明书。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料采用喷涂施工工艺，设备选用双组份喷涂设备。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料A组分外观黄色或浅色液体，无凝胶、结块。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料喷涂后凝胶时间为≤10s。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料施工快，移动方便单机日施工1000m²以上。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料固化快10秒内凝胶，1分钟达步行强度。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料在混凝土、玻璃钢、木材、钢材等材料表面具有优良的粘接性能。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '抗爆涂料力学强度极高，既有塑料的高强度，又有橡胶的高弹性。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '抗爆涂料适用工况。', '', '抗爆涂料施工便捷、用途多样、且兼具防腐、防水功能，可广泛用于商业、工业、军工等各个领域：如石油化工企业中控室、人员休息室、实验室的抗爆改造，小型武器、防弹背船和潜艇等甲板、海运通道及管道和储罐等的防护。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '抗爆涂料制造工艺流程图。', '', '多元醇 --(真空加热脱水)--> 无水多元醇；异氰酸酯 + 无水多元醇 --(反应)--> 半预聚体 --> A组分；聚醚胺 + 扩链剂 + 填料+助剂 --(高速搅拌分散)--> B组分；A组分 + B组分 --(喷涂成型)--> 抗爆涂层', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '抗爆涂料应用案例举例说明。', '', '（1）金陵石化建筑墙体（内、外）喷涂抗爆涂料，喷涂厚度2mm，用量达5000m²，起保护人员安全的目的。\n（2）北二路改造工程，抗爆涂料喷涂玻璃钢管道，累计应用3km，喷涂厚度3mm，提升管道抗外力破坏的能力。\n（3）中海油井下油管外壁喷涂抗爆涂料，喷涂厚度2mm，起耐腐蚀、防结垢、抗爆作用。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '写出抗爆涂料喷涂施工过程中几点注意事项。', '', '（1）控制合适的喷涂温度、压力，防止出现混合不匀，导致涂层质量问题；\n（2）施工时下一道要覆盖上一道50%，保证厚度均匀，俗称"压枪"；\n（3）多遍喷涂时，应水平及垂直交叉式喷涂，保证厚度均匀；\n（4）喷涂厚度一般1~3mm，根据现场工况和客户需求确定。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '抗爆涂料的耐温性能。', '', '长期耐温可达80℃。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '抗爆涂料的耐腐蚀性能。', '', '耐原油、污水柴油性能优异，耐碱、盐性能较好，耐酸、耐汽油性能稍差。目前正在进行技术提升，进一步提高抗爆涂料耐腐蚀性能。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '抗爆涂料的施工周期怎么样。', '', '施工周期短，单机施工达1000平方米/天。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '底材处理质量对抗爆涂料涂装质量具有重要影响，分别描述混凝土和钢材的表面处理方式。', '', '（1）混凝土：表面杂质和缺陷的清理→表面修补找平\n（2）钢材：除油→除锈', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '抗爆涂料性能优异主要体现在哪几个方面。', '', '（1）力学强度极高：既有塑料的高强度，又有橡胶的高弹性；\n（2）在混凝土、玻璃钢、木材、钢材等材料表面粘接性能优异；\n（3）涂层致密无接缝：防腐、防水效果极佳；\n（4）耐候性优良，使用寿命长。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '抗爆涂料施工快捷体现在哪几个方面。', '', '（1）固化快(10s内凝胶,1min达步行强度)；\n（2）施工快，移动方便，单机日施工1000m²以上；\n（3）不流挂，一次施工达到厚度。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉防腐管道是在钢管内壁烧结玻璃质无机釉层形成的复合防腐管道。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层最高使用温度可达300℃。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层耐油田污水、采出液及石化领域腐蚀性流体介质。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层内壁光滑，能防垢蜡沉积。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层与钢管基体附着力好，不老化，使用寿命长。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉防腐管道耐磨损性能优异。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉防腐管道生产工艺流程：进管→喷砂除锈→压缩空气吹扫→喷涂釉料→高温烧结→冷却→成品检验。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '钢管喷砂除锈前应表面无油、无锈，除锈等级达到Sa2.5级。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉喷涂后进入烧结炉高温烧结，使釉层与基体熔融结合。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '烧结后管体应冷却至室温方可进行检验与包装。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层厚度应均匀，无漏喷、无流挂。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层外观应平滑，无裂纹、气泡、无剥落等缺陷。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层检漏采用电火花检测，要求无漏点。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层附着力应符合要求，无脱落。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层耐急冷急热，经冷热循环后无开裂、剥落。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉防腐管道适用于石油、石化、市政电力等领域地面输送原油、污水的管道。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉防腐管道输送介质温度一般不超过300℃。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '我公司现有地面管道外防腐产品有环氧陶瓷、玻璃釉防腐管道。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉防腐管道连接采用焊接或法兰连接。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '焊接连接时应对焊口釉层进行保护，焊接后对焊口进行补口处理。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层为无机材料，耐候性好，适用于地面敷设。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层在阳光照射下不老化，适合长期地面敷设。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
