  (6, '玻璃釉防腐管道可用于输送原油、污水等介质。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉烧结温度应控制在工艺范围内，保证釉层质量。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉层检验项目包括外观、厚度、附着力、漏点检测。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉防腐管道存放时应防雨、防潮。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉防腐管道焊口补口材料应与釉层相容。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉防腐管道出厂前应进行成品检验，并挂合格证。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉防腐管道使用寿命可达30年以上。', '', '【原扫描内容：填空第31~40题】', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '管道的堆放层数应符合要求，公称直径200≤DN＜300mm的管道，堆放层数为≤8层。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '管道最底层应垫木楔或采取其它措施防止管道滚动。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '施工安装的管道卸车时应吊运管道，不得抛扔。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '施工安装常用工具主要有倒链、吊带、对口器、电焊机等设施。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '配套各种规格的法兰、弯头、三通等管件（可带扩口或堆焊短节），满足现场安装需要。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '施工安装验收需按照GB50819油气田集输管道施工规范验收。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '喷砂除锈后采用压缩空气吹扫管体内壁。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '玻璃釉防腐管道运输、安装过程中，应防止管道跌落、磕碰，不得使用重物敲击管道外壁，防止釉层造成损伤。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '施工过程中，布管时应吊运管道，不应在地面拖拽。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '焊口对接时不得撬管道的内壁。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '玻璃釉防腐管道的主要特点有哪些。', '', '耐高温；釉层为玻璃质无机材料，最高使用温度可达300℃；耐腐蚀：耐油田污水、采出液及石化领域腐蚀性流体介质；耐磨损：耐磨性优异；防垢蜡沉积：内壁光滑；附着力好，不老化，使用寿命长。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '请简述玻璃釉防腐管的应用领域。', '', '适用于石油、石化、市政电力等领域地面输送原油、污水的管道，也可用于高温、腐蚀性介质管道的外防腐。\n【AI补齐：简答第3~10题（原扫描缺失）】', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述玻璃釉防腐管道的生产工艺流程。', '', '进管→喷砂除锈→压缩空气吹扫→喷涂釉料→高温烧结→冷却→成品检验→包装存放。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述玻璃釉层的主要性能指标。', '', '耐高温（最高可达300℃）；耐腐蚀（耐油田污水、采出液及石化腐蚀性介质）；耐磨损；内壁光滑防垢蜡沉积；附着力好、不老化。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述玻璃釉防腐管道施工安装的注意事项。', '', '卸车、布管时应吊运，不得抛扔或在地面拖拽；焊口对接时不得撬管道内壁；防止跌落、磕碰，不得用重物敲击管道外壁；焊接后对焊口进行补口处理。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '为什么玻璃釉防腐管道具有耐高温性能？', '', '釉层为玻璃质无机材料，经高温烧结成型，结构稳定、耐高温，最高使用温度可达300℃。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述玻璃釉层质量检验的方法。', '', '外观检验（平滑、无裂纹、无气泡、无剥落）；厚度检验；附着力检验；电火花漏点检测（无漏点）；耐急冷急热检验。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述玻璃釉防腐管道相比普通钢管的优势。', '', '耐腐蚀、耐磨损、耐高温；内壁光滑防垢蜡沉积；不老化、使用寿命长；降低输送阻力与维护成本。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述玻璃釉防腐管道存放的要求。', '', '堆放层数应符合要求（如200≤DN＜300mm时≤8层）；最底层垫木楔防止滚动；存放于干燥通风处，防雨防潮。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述玻璃釉防腐管道运输的要求。', '', '防止跌落、磕碰；卸车时吊运、不得抛扔；不得用重物敲击管道外壁以防釉层损伤；长途运输应捆装牢固。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消器是一种用于消除硫化氢的捕消装置。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消器由干粉状硫化氢捕消剂和喷射装置两部分组成。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消剂由反应剂、疏水剂和分散剂等原料组成，与硫化氢发生反应。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '喷射装置用来存储并喷射硫化氢捕消剂，原理与干粉灭火器相似。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消器主要有手提式、推车式两种。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消器针对硫化氢气体泄漏主要起到预防和应急处置的效果。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消器生产设备一套，包括反应釜2台，干燥设备、研磨设备、灌装设备各一套，年产能500吨。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消器出厂检测项目包括外观、含水率、硫化氢捕消效率。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消器规格型号：4kg-手提式硫化氢捕消器（BLJYS04型）、16kg-推车式硫化氢捕消器（BLJYT16型）。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '使用捕消器进行操作前，应先佩戴好防护用品，应该在泄漏源的上风进行操作。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '手提式硫化氢捕消器试验压力为1.2MPa（+20℃）。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '推车式硫化氢捕消器工作压力为1.2MPa（+20℃）。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消器的驱动气体为氮气。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消器的使用温度为（-20~55）℃。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '产品应用清洁、干燥、无泄漏的容器包装，净质量误差不应大于1%。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '2020年硫化氢捕消器累计用量达57吨。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消器的捕消效率为≥95%。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消剂为白色固体粉末，含水率要求≤3%。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '硫化氢捕消器填料规格为超细干粉。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '硫化氢捕消器是如何起到预防作用的。', '', '气体检测→发现硫化氢气体→喷射硫化氢捕消剂预防中毒事故发生。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '硫化氢捕消器是如何起到应急处置作用的。', '', '硫化氢泄漏→区域喷射→转化为稳定硫化物防止事故扩大。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '硫化氢捕消器产品特点。', '', '（1）快速：在混合充分10分钟内即可出现脱硫效果；\n（2）高效：脱硫能力极强；\n（3）安全：脱硫过程温和，无燃爆危险；\n（4）便利：加注和产物移除便利，不会对生产工艺造成影响；\n（5）环保：本品及其脱硫产物易被微生物降解。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '硫化氢捕消器适用工况。', '', '硫化氢捕消器适用于石油化工、有机化工、市政工程、维修工程、油气田等各种可能含有硫化氢作业的场所，起到了预防和应急处置的效果。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '硫化氢捕消器工作原理。', '', '（1）发生硫化氢泄漏时，空气中弥漫大量高毒硫化氢分子；\n（2）使用硫化氢捕消器喷射后，捕消剂与硫化氢发生碰撞、吸附、反应；\n（3）在极短时间内，硫化氢生成稳定的硫化物，并沉淀。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '硫化氢捕消器制造工艺流程。', '', '分散剂+反应剂+疏水剂 → 反应釜搅拌 → 干燥 → 研磨 → 分离除尘 → 成品 → 成品灌装', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '列举三个采购硫化氢捕消器的客户及采购量。', '', '下表中任何三个厂家均可。\n工程名称 | 总瓶数 | 总重量（kg）\n上海石化消防工程有限公司 | 360 | 2640\n淄博鲁峰（齐鲁石化） | 392 | 1568\n齐鲁商业（江苏油田、扬州） | 269 | 2756\n淄博艾尔玛（北京燕山石化） | 350 | 2528\n淄博齐鲁商业有限公司（青岛石化） | 230 | 1280\n淄博艾尔玛（荆门石化） | 250 | 1600\n淄博爱尔玛 | 164 | 1640\n淄博鲁峰（齐鲁石化） | 178 | 2152\n石化总厂 | 176 | 1160', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '不同规格的捕消器能够去除多少数量的硫化氢气体？对应硫化氢浓度是多少？最适用于那种浓度范围的硫化氢气体？', '', '按硫化氢捕消器的实际含量除以5为中和硫化氢的量，可以在各浓度下进行中和反应。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '1000平方米车间理论上应该配备多少硫化氢捕消器？', '', '假设车间占地面积为1000平方米，高为8米，ppm值为1000，硫化氢充分扩散的情况下，考虑到硫化氢的危害性，及空气的流通性，应使用过量捕消剂进行中和反应，应不少于100千克，因此手持型硫化氢捕消器应至少配备25台。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '对应的产品不同工况现场的配置要求是什么？', '', '硫化氢捕消器产品应放置在干燥、阴凉处，并按使用说明书定期检查。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '合同当事人法律地位平等，坚持自愿、公平和诚实信用、公序良俗、绿色原则。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '企业法人以其注册资本为限承担有限责任，自然人、个体工商户、合伙企业的出资人需承担个人无限连带责任。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '合作对象的资信审查，常用工具有裁判文书网、全国法院失信被执行人信息系统。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '授权代理内容方面审查除要加盖有对方单位的公章、法定代表人签字外，还必须有授权委托的具体事项、权限范围以及委托代理的时间期限相符。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '合同正文约定条款包含合同标的、价格、质量、时间、履行方式等。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '法院选择不得违反专属管辖和级别管辖的规定。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '对方迟延履行合同主要义务时及时发出书面通知文书（书面催告），在满足中止或解除合同条件及时发出，并保存证据。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '向人民法院请求保护民事权利的诉讼期间为三年。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '诉讼时效期间从知道或者应当知道权利被侵害时起计算。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '诉讼时效最长不超过二十年。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '可供当事人协议管辖的法院。', '', '原告所在地、被告所在地、合同签订地、合同履行地、标的物所在地。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '直接业务人员的证件证据方式。', '', '（1）业务正常履行过程中，注意留存我方履行合同主要义务的证据，如供货合同中对方的签收货物的单据；建设工程施工合同中的施工资料等；（2）履行合同过程中对方明示违约或者存在违约迹象时应及时固定证据，并及时报领导及相关责任部门处理。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '诉讼时效中断事由。', '', '（1）起诉；（2）权利人主张权利；（3）义务人同意履行债务。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '还款协议书应记载的事项。', '', '（1）应载明还款协议所基于的基础合同关系及履行情况，尽可能的回避其他争议事项；（2）明确欠款金额及还款时间，分期返款的每期还款时间及金额应明确，同时应注明如任意一期未按期还款视为所有欠款提前到期；（3）可按民间借贷法律规定约定利息，可根据履行情况分别约定；（4）还款协议可对争议解决方式进行重新约定；（5）协议要加盖公章及法定代表人签字。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '超高分子量聚乙烯内衬油管适用于井温不超过95℃的介质环境。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '超高分子量聚乙烯内衬防腐使用压力≤25MPa。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '内衬油管衬管翻边检验中，在距管端40mm以内的内表面上，允许长度不超过1/2圆周、深度不大于1mm的挤压凹痕。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '超高分子量聚乙烯内衬防腐油管主要应用于油田有杆泵采油井用的油管，也可用于地面输送管道。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '内衬防腐油管用的超高分子量聚乙烯材料主要包括材料常温性能与老化性能检验，其中老化性能中的拉伸断裂屈服强度变化率指标≤15%。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '超高分子量聚乙烯内衬防腐油管是将超高分子量聚乙烯管缩径后衬入钢管内，经过加热去应力形成的防腐油管。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '内衬油管综合性能检测89型衬管从基管中拉出力≥12kN。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '超高分子量聚乙烯内衬防腐油管采用接箍连接的方式。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '超高分子量聚乙烯内衬防腐油管规格为2 7/8in油管、3 1/2in油管。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '3 1/2型超高分子量聚乙烯内衬防腐油管的衬管壁厚范围4.2~4.5mm。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '超高分子量聚乙烯内衬防腐油管执行的石油管理局标准名称为Q/SH10201889-2017内衬油管通用技术条件。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '超高分子量聚乙烯内衬防腐油管要求衬管材料拉伸屈服强度应≥20MPa。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '我公司井下防腐油管产品的种类有超高分子量聚乙烯内衬防腐油管、钛纳米涂层防腐油管、碳锆涂层防腐油管。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
