  (6, '内衬油管成品检验中，内衬油管综合性能检测纵向伸长率≤4.5%。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (6, '超高分子量聚乙烯内衬防腐油管能够有效减缓油管与抽油杆的偏磨以及油管的腐蚀，延长使用寿命。', '', NULL, NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '超高分子量聚乙烯内衬防腐油管的主要特点有哪些？', '', '耐磨损。耐磨性能是钢管的8~10倍，有效减缓抽油杆与油管的偏磨。耐腐蚀。耐酸、碱、盐腐蚀。防结蜡、防结垢性能优良。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述超高分子量聚乙烯内衬防腐油管的应用领域及作用。', '', '主要应用于油田有杆泵采油井，以及地面输送管道，有效减缓油管与抽油杆的偏磨以及油管的腐蚀，延长使用寿命。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述超高分子量聚乙烯内衬防腐油管的生产工艺流程。', '', '衬管挤塑 → 油管清检 → 打码 → 卸接箍 → 穿衬 → 应力分解 → 翻边 → 通径 → 安装接箍 → 检验 → 防护包装', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述超高分子量聚乙烯内衬防腐油管的长期适用工况温度、压力。', '', '超高分子量聚乙烯内衬防腐油管长期适用于介质温度不超过95℃，压力小于等于25Mpa的工况。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '简述超高分子量聚乙烯内衬防腐油管通径检验的要求。', '', '通径规顺畅、无卡阻地通过油管。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '超高分子量聚乙烯内衬防腐油管主要解决的问题？', '', '超高分子量聚乙烯内衬防腐油管主要解决偏磨腐蚀问题，有效减缓油管与抽油杆的偏磨以及油管的腐蚀，延长使用寿命。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '超高分子量聚乙烯内衬防腐油管运输与贮存规范有哪些要求？', '', '短途运输，根据用户要求散装或捆装；长途运输，必须捆装牢固。油管宜置于货架上，避免阳光长期直接照射，在空气中存放时间不宜超过12个月。油管在装卸、运输过程中，应轻吊轻放，避免碰撞和跌落等造成的机械损伤。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '超高分子量聚乙烯衬管的外观质量要求是什么？', '', '衬管表面应光洁，无夹杂、凹坑等缺陷，壁厚均匀。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '73型与89型超高分子量聚乙烯衬管外径尺寸及偏差。', '', '73型衬管外径65±0.2mm，89型衬管外径79±0.2mm。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1),
  (7, '超高分子量聚乙烯内衬防腐油管产品出厂检验项目。', '', '超高分子量聚乙烯内衬防腐油管产品出厂检验项目包括翻边外观、维卡软化温度、螺纹外观、紧密距、通径检验共5项检验。', NULL, 2, NULL, 1, NULL, 'seed:docx-20260921', 'seed:docx-20260921', b'0', 1);
